window.KKCORPUS={"_readme":"Merged interpretation corpus for the Observatory click-interpretation panel. MACHINE-BUILT by build_interp_corpus.py — do not hand-edit. Authored text lives in interp_blocks.json (synthesis) and Katie's Astrology Notes vault (keywords).","kw":{"planets":{"uranus":["Absolute Truth","Awakener","Breakthroughs","Individualist","Innovation","Liberation","Prometheus - Titan who Rebelled Against the Gods"],"jupiter":["Abundance","Alliances","Courage to Hope","Faith","Knowledge","Nature = Expand and Affirm","Saying 'Yes'","Zeus - King of the Gods"],"mars":["Action","Ares - God of War","Capacity to Assert","Conflict","Courage","Military","Nature = Energize","Physicality","Separating or Pulling Apart"],"venus":["Aphrodite - Goddess of Love and Beauty","Art","Beauty of Form","Desire","Equlibrium","Harmony","Nature = Magnetize","Peace","Pleasure","Unifying & Reconciling","Value"],"sun":["Authority","Consciousness and self-awareness","Enlightened Selfishness","EVERYTHING REVOLVES AROUND THE SUN","Holding it Together","Illumination","Initiative and Purposeful Assertion","Internal Constitution","Nature = to Build","Perception of the Soul","Sanity","When the Sun lies in a sign, those particular values will never fail you","Will to Exsist"],"saturn":["Boundaries","Dignity","Gives us the Ability to do What We do Not Feel like Doing","Kronos - Stern Father of the Gods","Limits","Nature = to Endure","Self Respect","Solace in Hard Work","Structure","Sustained Effort Over Time"],"mercury":["Critical Thinking","Data in, Data Out","Endlessly Curious","Fastest Planet - Speed of Thought Itself","Hermes - Messenger of the Gods","Interpretation","Messenger of the Gods","Nature = Communication","To Perceive and Reason"],"moon":["Defines Reality as We Experience it","Domestic Comfort","Experience of the Mother","Gatherings of the Masses","Impulse and Capacity to Gestate and Bring Forth","Nature = Nourish","Reflects","What Needs to be Healed & Regenerated Within","Your Average Mood"],"neptune":["Delusion","Dissolution","Dissolution of Ego Boundaries and Reality Structures","Dreams and Visions","Ideal","Mysticism","Myth and Religion","Non-ordinary States of Consciousness","Oceanic Depths of the Unconscious","Spirttualism","Transcendent","Utopian Social Ideologies","Window Beyond the Ego"],"pluto":["Ever-Evolving","Intensity","Overwhelming and Catastrophic Extremes","Pluto - God of the Underworld","Power Struggles","Repression","Resurrection","Transformative"]},"signs":{"sagittarius":["\"Truth is More Important Than Facts\"","Desire for 'Something New'","Greatest Enemy Would be Surrendering to Boredem","Natural Law","Philosopher","Sagittarius Rising","Scholar","Spirit","Stretching Our Boundaries","Voyager"],"aquarius":["A New Type of Human Being","Alienation","Aquarius Rising","Free-thinking","Independence","On the Outside Looking In","Paradigm Shifter","Process of Individuation","Traumatically Induced Emotional Distance","Utopian & Distopian"],"capricorn":["Absolute Mastery","Aim of Becoming an Elder","Capricorn Rising","Commitment","Dedication","Fascination of What's Difficult","If You Cut Corners, the Corners Will Cut You","Inherently moral, integrity counts","Looking at reality with a cold, clear eye, and adapting more effectively to its requirements","Methodical","Self-discipline","Survival of the Fittest"],"cancer":["Acceptance of Human Frailty","Cancer Rising","Creating a Safe and Restorative Home","Nurturing","Protective","Raw, Direct Emotion","Self-protective","Sensitivity","Shy about Life","The Great Mother"],"leo":["Acknowledgement","Attention is a life-giver. Being taken seriously is a life-giver","Creativity","Emotional Risk of Authentic Self-expression","Inspiration","Leo Rising","Letting it Matter if We are Received and Appreciated","Loyalty","Spontaneous Self-expression","Urge to be Celebrated","Urge to be Seen"],"pisces":["Ambient Psychic Energies","Enlightenment","Escapism","Exploration of Consciousness","Getting over ourselves","Kaleidoscope of Psychological Insights","Ocean of Consciousness","Pisces Draws its energy from the intensity of its downward dive in the moment","Pisces Rising","Primal Oneness with the Universe","Realm of archetypal patterns","Visionary Imagination"],"aries":["Aries Rising","Competitiveness","Initiative","Life Choosing Existence Over Surrender and Extinction","Moral Relativism","Playing to Win","Primal","Quick","Raw Strength","Spontaneous","Survival Instinct"],"libra":["Balance","Diplomatic","Libra Rising","Making Peace with Paradox","Perceptual Intelligence","Perfect Equilibrium"],"virgo":["Breaking Things Down Into Components","Details","Editing","Lineage","Processes","The Comparison of the Ideal to the Actual","Virgo Rising","Wanting to be Seen as Competent"],"taurus":["Connection with the 5 Senses","Consistent","Natural Habitat","Quality","Silence","Sticking with the Familiar","Taurus Rising","Wisdom of Simplicity"],"scorpio":["Detective","Focused version of Mars","Psychological Truth","Raw Reality of Life","Scorpio Rising","Unflinching Insight","Urge to Face all Emotionally Charged Truths squarely and courageously"],"gemini":["Duality","Dynamic","Endless Learning","Eternal Quest for Information","Gemini Rising","Insight","Mental Energy","Openness to the Unexpected","Versitile"]},"houses":{"2":["\"Gates of Hades\"","Ethics of How We Earn","Financial Habits","Livlihood","Maintaining and Substantiating One's Lifestyle","Material Basis of Survival","Material World","Money","Proving One's Self to One's Self","Resources that Support Inner Peace","Self-worth","Sense of Legitimacy in this World"],"10":["Achievement","Aspects of the Self that are Most Visible to the Public","Community","Higher Calling Beyond Profession","Mission in the World","Pinnacle of a Person's Glory","Public Mission","Purpose of Life","Rank or Position in Society","Reputation","Social Status"],"1":["Actualization of the Soul","Appearance","Beginning of All Actions","Identity","Level of Energy","Life","Persona","Personality","Physical Constitution","Physical Life of the Body","Self","The kind of 'grit' a person is made of","Where Spirit and Body Meet and Integrate"],"12":["Addictions","Attachment Triggers Loss","Disappointments","Evolution of Consciousness","Hidden Enemies","House of Bad Spirit","Impact of Fear on the Conscious","Imprisonment and Confinement","Mental Illness","Mystical Courage","Non-Attachment","Psychic Thought","Sacrifice","Secrets and Scandals","Self Undoing","Separation of Consciousness from Personality","Solitude","Spiritual Goals","Suffering","Suppression","Things That Happen Before Birth","Transcendence","Virtue"],"4":["Adult Life - The Home Each Person Creates for Themselves","Ancestral Legacy","Childhood Traumas","Early Life - Environment Provided by the Parents","Ethnic, Cultural, and Ideological Heritage","Home","How We Were Parented but also How We Parent","Parents","Paternal Circumstances into which a Person is born","Pride and Sense of Nationalism","Private Life","Relationships Which are Mutually Anticipated to Last for a Lifetime","Sense of Mutual Obligation","The Foundation that Stands Under All the Things that Support Us","The World Inside Us"],"6":["Animals and Pets","Bad Fortune","Bosses and Jobs","Daily Regimen","Duties and Responsibilities","Facing Adversity and Dealing with Personal Crises","Mentors","Military Service","Open Enemies","Physical Illness","Problems you can see","Routines","Work Itself"],"5":["Attractions","Children","Creations of Art, Music, and Performance","Delights","Love Affairs","Luck","Pleasures","Romance and Sexuality"],"11":["Audience","Being Useful to Each Other","Common Purpose Within a Group","Friends Who Assist the Native to Realize His Possibilities","Gaining Momentum","Group Activities","Group Identification","Hopes and Wishes","House of Good Spirit","Motivations for Future Success","Priorities"],"7":["Business Partners","Marriage","Projection","Relating","Relationships","The Other Party in Negotiations"],"9":["Connecting the Dots","Divination","Fathoming Cosmic Principles","Figuring Out the Meaning of Life","Higher Education","House of God","International Relations","Law","Long Distance Travel","Quest for Truth","The Larger World and the Larger Mind","Understanding The Universal Human Process","Where Ethical Values Can be Actualized into Practice"],"8":["Dark, Hidden, Repressed Contents of the Mind","Death","Death of the Old, Birth of the New","Debt","Denial","Embraces Everything in Life that Invokes Feelings of Fear in Us","Financial Assets from Marriage","Healing and Healers","Sex","Sexual Intimacy","The Esoteric","The Heart of Personal Issues","The Occult"],"3":["Development of Language","Heresy","Inner Knowledge and Self-arising Awareness","Interspace Between Worlds","Local Community","Neighborhoods","Practical Mind","Primary School Education","Questions","Reception and Transmission of Information","Religious Observances and Practices","Short Journeys","Siblings","What we have been 'taught' to see"]},"mundane_houses":{"4":["Agriculture, mining, and other resource industries","Political Party Out of Power when Chart is in Effect","Real Estate and its Value","Rural Population"],"5":["Celebrities","Entertainment Industry and Professional Sports","Gambling","Senate in U.S Gov't (Upper House of Legislature)","Speculative Finance","Tourism"],"2":["Changes in a Nation's Budget","Changes in Taxation","National Economy","Ordinary ups and downs of economic behavior","Productive Economy (generates goods and services)"],"6":["Condition of Labor Force","Interests of the Working Class","Mundane 6th House","National Civil Service","State of Public Health, Epidemics, and Disease","State of the Nation's Armed Forces"],"12":["Criminal Underworld","Hospitals, prisons, NGOs, and voluntary organizations","Institutions of National Life","Intelligence Agencies"],"8":["Deaths of Leading Politicians","Every Other Type of Economic Exchange Between Nations","Foreign Trade and Investment","Trade and Economic Treaties"],"3":["Economic Sectors of internal transportation, communication, media, and internet","Internal Communications","Internal Transportation","Internet","Media of a Nation","Public Schools and Primary & Secondary Education (but not Universities)","Relationships with Nations it shares Land borders with"],"10":["Executive Branch","Party in Power at the Time the chart Takes Effect","Power & Authority of the Gov't and the Nation as a Whole"],"7":["Foreign Affairs","Foreign Policies","International Incidents","Peace, War, Power Politics","Political treaties (but NOT trade treaties)"],"1":["General Condition, prosperity, health, and attitudes of the masses","Ordinary People of the Nation"],"9":["High Above and Far Away, Abstract Ideals","Maritime Affairs, Air Travel, Space Travel","Nation's Highest Court","National Judiciary","Religion","Universities and Higher Education"],"11":["House of Representatives (Congress) (Lower House of the Legislature)","Laws and the Processes by which they are Passed and Repealed"]},"aspects":{"trine":["120º from the 0º Aries point, corresponds with the cusp of Leo moving counterclockwise and the cusp of Sagittarius moving clockwise","Allows us to passively receive the beneficial conditions it presents to us without the intense focus of interest and attention characteristic of conjunctions","Divides the circle by 3","Evokes a strong sense of self-contentment, internal confidence, and general well-being","If we choose not to express ourselves through our trines they become latent and inactive","Lower Trine","More apt to represent inner states of consciousness manifesting as creative insight, visions of ideal expression, or a fuller awareness of factors that produce true harmony and artistic synthesis","Not driven to confront crises head-on, they often follow the line of LEAST resistance","Operates without friction and discomfort","Preservers of the status quo. They act like soothing sedatives, calmly smoothing out potential conflicts in a gentle, tranquil, non-abrasive manner","Relaxation, peace, harmonious reception, and pleasurable response.","The Fire element is emphasized, indicating expression that is innately creative, warming, and positive","With such a lack of pressure, strain, and tension, the trine doesn't supply the impetus needed to push us into decisive action in a challenging manner that fosters dynamic change"],"sesqui-square":["135º from the 0º Aries point - Counterclockwise associates with 15º Leo and Clockwise associates with 15º Scorpio","Apt to react to minor conflicts in an overly forceful manner, which tends to throw situations off-balance or blow them out of proportion","Common Denominator shared between Leo & Scorpio is that they are FIXED signs of the WESTERN hemisphere","Dealing with consequences of a lack of composure and self-restraint in interpersonal situations","Involves a greater degree of sudden upset and unexpected disruption that temporarily stuns or jolts our sensibilities or those of others we confront","Our ineffectiveness in controlling the situation evokes resentment and mild anger","Situations tend to break down of fall apart at the last minute, which leaves us feeling momentarily scattered and disorganized","Tends towards extremism in behavior, leading towards inconsistencies in expression","Upper Sesqui-Square"],"quincunx":["150º from the º0 Aries point, connects with the cusp of Virgo moving counterclockwise and the cusp of Scorpio moving clockwise","Can be viewed more aptly as a 'nagging' problem, operating over an extended period of time","Corresponds with signs that naturally analyze and dissect, motivated by a need to make essential modifications that improve the capacity to function","It lacks the intensity and strength of impact required to bring its tension to our surface consciousness until, almost in a fateful manner, circumstances develop forcing us to give it our utmost attention","Its basic role is that of breaking down and removing those non-effectual attitudes that interfere with our ongoing growth","Seems to require that we observe our usage of energies in a carful, methodical way so that we can learn how to become more selective, discriminating, organized, and efficient in handling the activities represented by the planets involved","Suggests that the planets involved first must re-assemble their energies before they can be properly utilized in a manner that is beneficial"],"opposition":["180º from the 0º Aries point, corresponds with Libra, operating thru the Libra Dwad in the Libra Decan","Actually initiates the waning aspect cycle when separating","Allowing for a fuller 'face-to-face' awareness of the functions of both planets","Capacity for psychological projection, in which the undervalued planet's expression is projected onto another individual who then must play out that planet's role","Could represent indecision, resulting in an inability to take any type of action","Division of the circle by 2","If resistance towards integration persists, then we can expect both planets to behave antagonistically, constantly pulling apart or battling each other","It is when one planet becomes too closely identified with at the expense of the other that the fine balance required for constructive activity becomes difficult to achieve","Poorly integrated oppositions indicate a lack of self-determinism","The aspect most prone towards externalizing stress thru relationships in its attempt to promote greater awareness of ourselves in reference to others","The exact opposition point is apt to indicate a degree of enlightenment that allows the individual to observe the planetary energies from a more meaningful vantage point","The greater purpose is learning how to share ourselves with others in a sensible manner allowing for an adequate measure of fair-play, justice, and give-and-take","We are not benefited by constantly giving in to people and challenging situations simply to avoid tensional confrontations","When well integrated, the planets enhance each other's functions, pulling together for the benefit of the greater whole","While the planets can never blend together in the manner of the conjunction, they can reinforce each other's needs in a mutually agreeable manner"],"semi-sextile":["30º from the 0º Aries stationary point moving counterclockwise correlates with the sign Taurus, and the sign Pisces moving clockwise","Corresponds to both Earth and Water signs, can be interpreted as an aspect of a receptive, internalizing nature","Divides the circle by 12","Since the energy level here tend to be insufficient for the activation of full potential, semi-sextiles require some measure of personal exertion and determination if we are to spur them into resourceful activity","Stabilizing, conserving, and preseving","Taurus seeks to firmly secure worldly assets for strictly personal usage and gratification, while Pisces seeks spiritual goods that can eventually be released back into the world for the ultimate betterment of all","The Attraction of resources that need further development"],"semi-square":["45º from 0º Aries, counterclockwise associates with the 15º Taurus and 15º Aquarus moving clockwise","Can supply us with the extra measure of strength and conviction needed to help us sustain our efforts in minor, not too obvious, ways","Division of the circle by 8","Fixed quality undertones might suggest some degree of stamina, persistence, and purposefulness","Irritability, irksomeness, and mild frictional strain. Nuisance'","Taurus and Aquarius are both Fixed signs of the Eastern Hemisphere","Willful attitudes that tend to keep us rut-bound, unadaptable, and uncompromisingly resistant to needed changes"],"sextile":["60º from the 0º Aries point, moving counter clockwise beings us to the cusp of Gemini and the cusp of Aquarius moving clockwise","Allows us to become curious about life and its unlimited variation. Represents active expression of creative forces seeking constructive synthesis","An explorative aspect, eager for learning new experiences","Can feel quite at home living exclusively in his head and thus may not be motivated to apply its promise in a tangible manner","Coax us to self-express freely according to various options and alternatives provided by our environment","Division of the circle by 6","Emphasized association with the Air element, suggesting a mentally energizing aspect","Natural catalysts for efficient brain and nervous system activity","Stimulative and less content with a sense of sameness","Urge us to obtain helpful information about life through objective observation","Where one can apply much intelligence and inventiveness in expressing the principles indicated"],"square":["90º from the 0º Aries point, counterclockwise brings us to the cusp of Cancer and the cusp of Capricorn moving clockwise","Agitates the planets involved, pressuring them to suppress energies or express with forceful assertion. Inhibition and over-drive are problematic.","Both the upper and lower square link with the midpoint of each hemicycle, they represent major tension points within the entire cycle","By denying our ability to handle challenges, we only evoke the frustrating, self-blocking aspects of the square","Challenge us to act rather than continue to endure the pain and discomfort they generate","Correlates with the Earth-Water elements and in naturally inclined to draw its energies inward","Corresponds with the Cardinal quality exclusively","Crisis-oriented, forcing us to act in an explicit manner that allows for purposeful turning-points in consciousness","Divides the circle by 4","Internalizing in its stress. Its tensions are rooted from within.","Its frictional nature is best relieved thru decisive action demanding direct struggle, aggressive effort, and greater energy expenditure","Planets involved in square aspect interact from a somewhat defensive pose and do not easily synthesize","Probably the most situational of all aspects in that it forces us to eventually confront conflicting circumstantial affiars that can only be satisfactorily resolved thru head-on no-nonsense encounter.","Provides us with much drive and impetus to initiate changes","Provides us with the powerful thrust of concentrated energy needed to confront and overcome major obstacles that stifle our growth process","Quite uncompromising","Seems to follow the line of MOST resistance","Square","Tension here can feel exhilarating as long as it is flowing in action and not dammed up","The faster moving planet often feels boxed in, inhibited, and resentful of the demands imposed upon by the slower moving planet until it has struggled to reorient itself","The momentum to develop further"],"upper square":["A sense of inadequacy, guilt, and a fear of consequences are more emphasized, resulting normally in self-blocking","Corresponds with the sign Capricorn, operating thru the Capricorn Dwad in the Capricorn Decan","Drive to manage and maintain one's own boundaries in the social environment is emphasized","Forced to recognize our obligations here as strength-producing rather than burdensome","Generate suppression or inhibition due to our struggle with external control factors (symbolic authority figures in our life)","Goads us to achieve and accomplish in the outer world","Promotes greater self-reliance plus the capacity to build firm, well-structured foundations in the greater world around us","The individual is consciously aware that his personal drives are often antagonistic to what is expected of him by his society"],"upper trine":["A source of personal uplift and inspiration, enabling us to elevate our consciousness to lofty levels of idealism, understanding, and wisdom","Can be used for the enlightenment of others as well as for self-illumination","Corresponds with the sign Sagittarius, operating thru the Sagittarius dwad in the Sagittarius Decan","Could foster undue optimism, blind faith, procrastination, and irresponsibility","Generosity of spirit","Great expectation and hope for the best","Humane, tolerant, philanthropic, and freedom-seeking","Often can make us innocently unaware of stress signals in our life","Personal gratification can occur as a result of social interaction","Psychic awareness and the comprehension of highly abstract principles","Seeks out creative release thru more expansive avenues of collective expression. Tends to be less egocentric","The ability to apply foresight in personal affairs is often excellent","The areas of life (houses) and behavioral attitudes (signs) linked with a trine reveal where and how we can instill faith in ourselves and have unquestioned trust in higher protection or inner guidance","Urges us to benevolently share our blessings with others"],"novile":["Ability to see meaning in everything, thus is an aspect of rebirth based upon meaning","Can be seen as the symbol of initiation, the emergence into a totally new realm","Can describe an individuals inner 'ideal'","Can represent the identification of self with a purpose and function related to a global or universal scheme","Corresponds with 10º Taurus moving counterclockwise and 20º Aquarius moving clockwise","Dividing the circle by 9","Expresses itself through compassion, tolerance, forgiveness, benevolence, and a willingness for personal sacrifice for the upliftment and healing of humanity","May assist in our attempt to unify energies, resulting in a more encompassing sense of oneness","May indicate spiritual rebirth or initiation in the realm to which the planets refer. Signifies birth our of captivity","Represents a process of gestation by means of which the idea or the beautiful form is brought to a condition of organic viability","Selflessness and breadth of universal understanding","Subjective growth through sacrifice, selflessness, and deep assimilation of spiritual insight","Tests the depths of our abilities, operates from an unconscious level and often concerns something from the past that may tend to hold our potential in limbo until we strive to give ourselves altruistically from the heart and not just mentally"],"lower sextile":["Adaptability becomes a positive asset, allowing us to undertake productive action successfully","Associated with the sign Gemini, operating through the Gemini Dwad in the Gemini Decan","Being too susceptible to mundane distractions, we have difficult focussing our energies and thus tend to restlessly hop around without taking the time or making the effort to adequately digest and assimilate what we have encountered.","Mentally agile, open, and eager to learn new things","Stimulates mentation, enabling us to make logical, concrete connections between the various components of any immediate experience","Superficial Awareness","The attraction of opportune experiences in the everyday environment that can help us gather factual knowledge about life which can use for our personal advantage"],"quintile":["Allows us to grasp a holistic overview, plus grant us the power and single-mindedness required to bring such a rare perspective into sharper focus, integrating all intricacies involved into a more unified whole","Associated with 12º of Gemini moving counterclockwise and 18º of Capricorn moving clockwise","Associated with the use and abuse of power and authority","Concerned with the faculties in which we know, and the means by which we receive and communicate knowledge and informtion","Describes the potential of abilities normally considered exceptional or gifted, and abilities that are not necessarily developed or conditioned by experiences in the external environment","Division of the circle by 5","Enables ones to construct (mental) form in an ideal manner that most perfectly reflects the archetypal purpose of that form","Indicative of uncommon facets of human capacity expressing a notable degree of creative genius, rare insight, and mental artistry","Linked with a pronounced tendency to be very one-pointed and intensely driven in a specialized field of study","Not surprising if, for most of us, quintiles are only active during dream activity, deep meditation, or other altered mental states of consciousness","Perhaps quintiles in the natal chart only fulfill their lofty, universal potential once we have struggled to become more self-realized"],"upper quincunx":["Allows us to transmute our awareness to even higher levels of consciousness","Centered around the use or abuse of intense desire and willful emotionality","Compels us to probe deeply within ourselves in an attempt to strengthen the awareness gained thru the preceding opposition phase","Corresponds with the sign Scopio, operating through the Scorpio Dwad in the Scorpio Decan","Its correlational focus is more psychological and permanent in its operation, since its associated with fixed water","Life will force us to inspect those personal attitudes that are best outgrown rather than retained"],"upper semi-square":["An underlying sense that there is something more to be experienced even beyond ideal cooperation","Brings a degree of authoritarianism that will need to be kept in check if this aspect is to become an asset","Can be sporadic and unsettling in its nature, presenting sudden minor obstacles often due to unforeseen actions of others","Can define strange quirks in human nature, implying social maladjustment that seems forever out-of-tune with standard conventions of society","Combines the more self-expressive fire-air element","Corresponds with the sign Aquarius, operating thru the Leo Dwad in the Gemini Decan","Deals more with the dispersal of energies into the community","Friction is felt whenever we try to force our ideals and goals upon others in an uncompromising, often insensitive manner","Inclines us to attempt to mould the environment according to our own social vision of how things should ideally be"],"upper sesqui-square":["Any attempt to act in devious ways only tends to further confuse issues at hand","Correlates with the sign Scorpio operating through the Taurus Dwad in the Pisces Decan","Disruption occurs due to our inner compulsion to try to remake others in order to appease our fixed desires of how they should behave","More indirect in expression than the lower sesqui-square","Tests our ability to tolerate and genuinely accept people as they are","Upper Sesqui-Square"],"upper semi-sextile":["Any ultimate benefit is easier realized once we adopt a genuine concern for selflessly serving humanity","Denotes spiritual possessions that we can share with others in a charitable, benevolent manner","Experiences that require the lease amount of ego-involvement","May first entail confronting 'unfinished business' from the past requiring the dissolution of self-will before potential here can be actualized","Represents perhaps the most delicate and other-worldly of all aspect phases","Stimulates us to activate latent resources that have stored up within the deeper levels of the psyche","The needs to make social adjustments beyond the usual level of give-and-take in relationships","The Upper Semi-Sextile correlates with the sign Pisces, operating through the Pisces Dwad in the Pisces Decanate","Transcendental undertones and can be more fully brought into active expression once we have consciously aspired towards altruistic, collective goals"],"conjunction":["Appears to operate directly through through behavioral traits rather than circumstantial affairs","Co-Presence","Conjunctions highlight, accentuate, emphasize, and give prominence to the planetary principles represented","Direct Blending Initiates Pure Activity","Division of the circle by 1","Few natal conjunctions (or none) suggests that the individual is less prone towards being self-driven","Highly self-contained and driven to act out is urges exclusively and independently","limited perspective of issues at hand","Normally has difficulty compromising or adjusting to needs beyond its immediate, self-generated ones","Resists external influences","Strongest in the cycle in terms of intensity, concentration, focus, and impact","The planets involved are compelled to pull together and operate as one singular unit","While planets in conjunction must always unite together in action, they won't always feel coordinated at all times"],"lower sesqui-square":["Apt to have an unquestioned belief in the rightness of our attitudes","Correlates with the sign Leo, operating through the Aquarius Dwad in the Sagittarius Decan","Falls midway between the self-indulgent lower trine and the self-corrective lower quincunx","Pressures us to realize the limits of our self-will, instills a degree of personal discomfort and frustration whenever we attempt to enforce our uncompromising demands in relationships","Represent a tensional point in the cycle wherein the natural urges of the lower show signs of becoming troublesome in relationships","Represents a somewhat abrasive display of egoism","The misguided expression of will tends to produce minor obstacles that thwart our ability to cooperate","The power-seeking, authoritative side of Leo is more evoked here than its joyous, creative side","We demand complete freedom from the control of others, but often try to establish this in an awkward, immature manner","We tend to come on too strong here at the expense of others"],"dissociate trine":["As Quincunxes pressure us to carefully analyze and make needed corrections thru reorganizing our energies, the individual may become too unnecessarily caught up with making minor adjustments in areas that really don't require them","Dissociate Trines involve underlying influences that tend to trigger psychological discord and uneasiness","Individual usually feels more ill-at-ease than would be reasonably expected","Involves signs that either Qunicunx or Square one another","Quincunx - individual does not easily adjust psychologically to the benefits he nevertheless readily attacts","Signs that Square - outer situations operate too smoothly to satisfy the inner drives of the individual","Since squares can be self-blocking, the individual may also harbor repressive attitudes that thwart his ability to feel self-satisfied"],"septile":["Associated with the 21º (and a half) Taurus moving counterclockwise and 8º (and a half) Aquarius moving clockwise","Can be interpreted in a super-personal sense as acts compelled by a collective need, an occult power or fate, and these may lead to sacrifice and a symbolic life","Discloses one's capacity to receive inspiration","Division of the circle by 7","Introduces the unpredictable, irrational elements of experience, symbolizing the ability to respond to the call of one's destiny","Mystical undertone is likely due to its urge to understand wholeness and completion","Potential capacity","Reveals a fated inevitability with a compulsion to certain actions, and unrecognized force with hidden activation","Self-knowledge, interior analysis, the search for ultimate meaning or wisdom, and involvement with introspective or research-oriented studies","The ability to sense the mysterious whole behind the parts of a subject","The capacity to embrace intellectually the formative idea or principle behind a thing and so participate in the dynamic energy which that idea imparts"],"upper novile":["Associated with the sign Aquarius, operating thru the Libra Dwad in the Libra Decan"],"lower novile":["Associated with the sign Taurus, operating through the Virgo Dwad in the Virgo Decan"],"dissociate square":["Attracts challenging situation that tend to force him to confront matters head-on, but he may psychologically lack the stamina and determination to deal with such demanding circumstances","Involves signs that either Trine or Sextile each other","Involving signs that Trine one another suggests that the individual's personal sense of harmony and well-being allows him to accept challenges with greater faith and confidence","Signs that Sextile - Has the potential to become more enlightened once the individual realizes that he can intelligently tackle his problems.","Signs that Trine - No matter how difficult situation tend to get, this individual inwardly believes that things will work out for the best","Signs that Trine - Problems here will not improve or go away unless he deals 'squarely' and realistically with such challenges","The inner drive required to work thru problematic outer obstacles is normally inadequate. And thus both types of dissociate squares are less prone toward accomplishments thru struggle and effort","The signs involved do not agitate each other, resulting in less impetus to take decisive action resolving predicament the square normally attracts","The underlying sextile influence can give extra self-encouragement and optimism","Underlying sextile influence may enable the individual to objectively recognize the reason for his inner conflicts rather than continue to unconsciously act them out in a habitual manner"],"dissociate sextile":["Both suggest a lack of easy facility typical of the standard sextile","Involves signs that naturally semi-sextile or square each other","Signs that Semi-Sextile - Tends to be a slight inner resistance towards learning new things","Signs that Semi-Sextile - There may be more gut-level instinctive know-how concerning the positive use of urges presented here plus a capacity to more carefully nurture the development of such urges","Signs that semi-sextile each other - individual has no trouble attracting constructive opportunities, but he may feel less stimulated by them and thus may pass them up","Signs that Square - He usually tries too hard to accomplish what is normally best obtained with less effort or else he may block himself from opening up to beneficial new experiences due to an inner sense of insecurity or inadequacy","Signs that Square each other - The experiences the individual attracts do not often satisfy his inner need for challenge and confrontation, and again prove less stimulating or appealing in the long run","The Key lies in knowing how much effort is needed for best results","The passivity of the semi-sextile undertone psychologically discourages open self-expression"],"lower square":["Bottling up internal conflicts. Tends to be caught up with negative past experiences that he has difficulty putting into proper perspective","Challenge is to discover what attitudes promote or thwart his capacity for self-nurturance","Corresponds with the sign Cancer, operating thru the Cancer dwad and in the Cancer Decan","Exposes our root vulnerabilities, disclosing where we tend to act or react irrationally and regressively. Likely to be overly defensive here","Helps us develop a sense of depth","One essential purpose is the constructive digestion and assimilation of experience, and this call for discrimination","Stress shown is often indicative of subconscious conflict that tends to threaten our personal sense of security","We are challenged thru the the pressure of internal and external life crises to confront those behavioral attitudes that, when left unresolved, continuously uproot our psychological foundation","What facets of past experience are worth of psychological digestion and assimilation. That which is not supportive to our ongoing growth must be released"],"upper sextile":["Can suggest an out of the ordinary capacity for mental and social enlightenment","Corresponds with the sign Aquarius, operating thru the Aquarius Dwad in the Aquarius Decan","Encourages innovative mental expression and allows us to perceive an overview of the many complex factors of any concept","Motivated to experiment with life's opportunities from a more impersonal, detached perspective","Scope of awareness is broadened and extended to a more social application of the principles involved","Tends to stimulate curiosity about the future development of present potentials","These energies are not easily self-disciplined and normally do not operate thru established methods and traditional procedures"],"lower semi-sextile":["Coaxes us to fertilize those budding interests and attractions that can result in creative self-expression","Correlates with the sign Taurus, operating through the Taurus Dwad and the Taurus Decante","Gentile stimulant, prompting us to develop an instinctual awareness of how and where values suitable for our growth can be built into our nature","Operate upon the level of unconsciousness survival instincts, facilitating necessary physical functioning and comfort","The initial drawing power to attract benefits on a smaller scale which can eventually become constructive personal assets"],"dissociate semi-sextile":["Conjunction type - could supply more drive and push towards the manifestation of potential assets as one learns to become more self-related and unified in direction","Involves influence of the conjunction or the sextile","Signs that sextile - his awareness of the value of his resources is better developed than one with the standard semi-sextile","Signs that sextile - the individual may be more psychologically curious about how potential resources can be applied","The conjunction undertone could suggest that the individual is not yet ripe and ready to work with his inner or outer resources until he is able to establish a better sense of identity or self image","The stimulation of the underlying sextile keeps the dissociate semi-sextile from being inertia-prone due to the fact that the individual is more psychologically restless and desires to do something with the potentials shown"],"upper quintile":["Correlates with the sign Capricorn, operating through the Leo Dwad in the Taurus Decan"],"lower trine":["Correlates with the sign Leo, operating through the Leo Dwad in the Leo Decan","Creatively self-expressive, pleasure oriented, and somewhat exhibitionistic","Due to the fixed undertone, the lower trine can steadily pour out its creative potential with little deliberation","Instinctively shunning whatever requires hard work and self-discipline, this individual would rather coast thru life establishing no serious objectives outside of personal sensual fulfillment","Laziness can result if self-satisfaction becomes too pronounced","Less prone to accept restriction and limitation as part of their world","Lower Trine","One's ability to shine, radiate, attract recognition, and gain popular approval is promised a suitable outlet","Seeks the pampered, effortless way of doing things"],"lower semi-square":["Correlates with the sign Taurus, operating thru the Scorpio Dwad in the Virgo Decanate","Developing a willingness to make practical, minor adjustments","Inclines towards hasty or premature evaluation","Leaves us feeling inconvenienced in some manner","Operates in a blind, subjective manner","Pressures us to adapt rather than stagnate","Serves as a psychological warning flag, indicating where we are becoming congested in our attitudes and unwisely stubborn concerning the need for a personal change","Teaches us to value and appreciate the variability of life, seeing small changes as presenting us with personal advantages","Tendency to become irritable and critical of issues at hand","Tendency to force matters in a one-tracked manner","Tension here is still in its rudimentary stage of formation within our consciousness - yet it is starting to become inwardly uncomfortable"],"lower quincunx":["Correlates with the sign Virgo, operating through the Virgo Dwad in the Virgo Decan","Frustrations in our routine activities until we learn to make those necessary adjustments that result in greater competency, efficiency, orderliness, and perfection of technique or skill","Indicates how and where a needed mental adjustment must occur before loose ends here are to be consciously recognized and more clearly ironed out","Out-of-focus and somewhat on the fence concerning the correction of minor flaws of operation that keep problematic areas unresolved","Teaches us that the creative power fully realized at the lower trine phase must be properly controlled thru discrimination if it is to reach a state of great perfection"],"lower quintile":["Correlates with the sign of Gemini, operating through the Libra Dwad in the Libra Decan"],"upper septile":["Corresponds with the sign Aquarius, operating through the Taurus Dwad in the Aqaurius Decan"],"lower septile":["Corresponds with the sign Taurus, operating through the Capricorn Dwad in the Capricorn Decan"],"semi-quintile":["Dividing the circle by 10"],"undecagon":["Dividing the circle by 11"],"dissociate conjunction":["Individual may not feel as motivated to assert himself in the direct, spontaneous, head-strong manner of the standard conjunction","Involves signs that naturally semi-sextile each other","May express with less coordination or strength of purpose","May suggest the individual may be able to draw from inner resources of a less apparent nature","Tends to hesitate before thrusting himself into the activity","Typically one becomes confused as to how to best synthesize the different behavioral traits of the signs, resulting in mild frustration"],"applying opposition":["May imply a more difficult time sharing energies represented in an actual relationship due to a measure of self-interest"],"separating opposition":["May reflect a greater amount of awareness concerning the functions of both planets involved and how to utilize these energies in a relationship with a greater sense of give-and-take"]},"elements":{},"other":{"mundane analysis":["2025 Aries Solar Ingress Chart"],"gods":["Aphrodite - Goddess of Love and Beauty","Ares - God of War","Hermes - Messenger of the Gods","Kronos - Stern Father of the Gods","Pluto - God of the Underworld","Prometheus - Titan who Rebelled Against the Gods","Zeus - King of the Gods"],"houses":["Houses - Where and How"],"mundane houses":["Mundane 6th House"],"planets":["Planets - Agendas"],"signs":["Signs - The Tools Provided"],"aspects":["Square","Waning (Upper) Aspects - When the faster planet is separating from the opposition point of the slower planet and is heading toward a reconjunction","Waxing (Lower) Aspects - When the faster planet is approaching the opposition point"],"general definitions":["Waning (Upper) Aspects - When the faster planet is separating from the opposition point of the slower planet and is heading toward a reconjunction","Waxing (Lower) Aspects - When the faster planet is approaching the opposition point"]},"combos":[{"tags":["gods","venus"],"phrase":"Aphrodite - Goddess of Love and Beauty"},{"tags":["gods","mars"],"phrase":"Ares - God of War"},{"tags":["gods","mercury"],"phrase":"Hermes - Messenger of the Gods"},{"tags":["gods","saturn"],"phrase":"Kronos - Stern Father of the Gods"},{"tags":["lower trine","trine"],"phrase":"Lower Trine"},{"tags":["mundane 6th house","mundane houses"],"phrase":"Mundane 6th House"},{"tags":["gods","pluto"],"phrase":"Pluto - God of the Underworld"},{"tags":["gods","uranus"],"phrase":"Prometheus - Titan who Rebelled Against the Gods"},{"tags":["aspects","square"],"phrase":"Square"},{"tags":["sesqui-square","upper sesqui-square"],"phrase":"Upper Sesqui-Square"},{"tags":["aspects","general definitions"],"phrase":"Waning (Upper) Aspects - When the faster planet is separating from the opposition point of the slower planet and is heading toward a reconjunction"},{"tags":["aspects","general definitions"],"phrase":"Waxing (Lower) Aspects - When the faster planet is approaching the opposition point"},{"tags":["gods","jupiter"],"phrase":"Zeus - King of the Gods"}]},"blocks":{"planets":{"Sun":{"myth":"Helios drives his four-horse chariot through the high arch of heaven, seeing everything — and every night he sleeps in a golden vessel, carried back through the dark ocean to rise again. He is the energy that says 'I am I': strength, radiance, and the nightly surrender that makes morning possible.","natal":"The center that everything else orbits — vitality, identity, the will to Build. Where the Sun stands is where you are asked to shine consciously: to author your life rather than merely undergo it, to write the Internal Constitution by which everything else in the chart is governed. Its sign is the style of your becoming; its house, the stage where the light insists on falling. And the myth keeps its honest half: even Helios surrenders to the dark ocean nightly — the radiance is real only because it is renewed, not because it never sets.","mundane":"The actual head of government — whoever really calls the shots in the executive branch, not the national 'ego.' The Sun's dignity and aspects tell you plainly how the government will fare. Watch combustion: any planet within 8°30' is co-opted by the executive, used for the government's ends rather than its own.","actor":"the President / the executive branch","orrery_summary":"To Build · President / executive branch. The actual head of government and supreme authority; its condition and relationships describe how executive power is operating. Combustion shows another actor being drawn into the executive's purposes."},"Moon":{"myth":"The Moon is many goddesses in one cycle: Selene giving herself in the dark, Artemis hunting free under the waxing light, Persephone eating the pomegranate and descending so the grain may grow again, Hecate waiting at the crossroads, Hera blazing full. She is the open bowl into which everything falls — the wheel of growing, maturing, passing away, and beginning anew: always, and always now.","natal":"The Reflecting One — Your Average Mood, the Impulse to Gestate and Bring Forth. The Moon is how you digest experience into feeling: what you reach for when no one is watching, the body's memory of being held, the Experience of the Mother carried forward as the way you mother yourself. She is never one thing because she is the cycle itself — maiden, mother, dark queen and crone in monthly rotation — and her sign tells you which goddess answers when you are tired, frightened, or tender. Fast and faithful, she times everything.","mundane":"The political class and public mood — the voiced layer of the nation. 'People (Moon)' is also sanctioned in Katie's usage, but compare the Moon with the 1st house and its ruler, the ordinary populace. When Moon and 1st-ruler are in harmony, political voice and national body remain aligned; a run of hostile aspects warns that they have separated.","actor":"the political class and public mood","orrery_summary":"To Nourish · Political class and public mood. The voiced layer of the nation; compare the Moon with the 1st-house ruler — the ordinary populace — to see whether political voice and national body remain aligned."},"Mercury":{"myth":"Born in the morning, by noon he had built the lyre from a tortoise shell, by nightfall he had stolen Apollo's cattle — driving them backward to erase every trace — and still talked his way onto Olympus. He is the messenger between all worlds, the one god with a passport to the underworld, who guides souls and sends dreams without asking payment. He invents the instrument, never the music: everything depends on whose companion he is.","natal":"To Perceive and Reason — Endlessly Curious, the Speed of Thought Itself. Mercury is the translator between worlds: data in, data out, but also soul in, soul out — the psychopomp who can carry a message from your depths to your daylight mind and back. His condition shows how you learn, name, connect, argue, and trick; the thief's gift is real (the backward-driven cattle live in every clever reframe), and so is the lyre. He has no agenda of his own — which is why the rest of the chart decides whether he serves the music or the theft.","mundane":"The national conversation: press, media, transport, trade documents, treaties-as-paper, the chattering classes. Strong Mercury = ideas drive events. Afflicted Mercury = the ideas on center stage are confused or dysfunctional, and communication and transport break down. Never far from the Sun — the intellectuals usually serve the established order.","actor":"the press and the national conversation","orrery_summary":"Communication · Press and national conversation. Media, transport, trade, and treaties-as-documents; its condition shows whether information and movement carry cleanly or become confused, dysfunctional, or interrupted."},"Venus":{"myth":"When Saturn cast heaven's severed creative power into the sea, foam arose, and Aphrodite grew up in it; where she first stepped ashore, the earth blossomed under her feet. She is the wealth that gives itself and grows more abundant in the giving — but refuse her tribute, as Hippolytus did, and the love-principle reverses into revenge.","natal":"To Magnetize — Value, Harmony, the Beauty of Form. Venus shows what you draw toward yourself and why; what you find beautiful is a confession of what you are. She was born from what the old order cut away and threw into the deep — your capacity for love rises out of exactly what was severed and discarded — and the ground flowers wherever she actually steps, meaning: where you give value, value multiplies. Her condition shows your power to attract rather than pursue; her shadow arrives whenever her tribute is refused, in yourself or another.","mundane":"The women of the nation — the women's vote, women's issues — plus the arts, culture, diplomacy, social peace, and the currency's grace. Dignified: contentment and prosperity. Debilitated: scandal, extravagance, women's concerns shoved aside, ugliness in public life.","actor":"women, the arts, diplomacy","orrery_summary":"To Magnetize · Women, arts, diplomacy, social harmony, and currency. What the nation values, attracts, reconciles, and gives beautiful form; condition distinguishes peace and prosperity from scandal, extravagance, exclusion, or public ugliness."},"Mars":{"myth":"The only son of Zeus and Hera, and unloved from his first day — the rejected brawler who fights for both sides and bellows like ten thousand men when wounded. Yet in him wakes the longing for Venus, his opposite and complement: their children are Fear and Terror, but also Eros and Harmonia. Whoever, like King Cadmus, serves him long enough to know him wins the daughter named Harmony.","natal":"To Energize — the Capacity to Assert, the courage to want something openly and fight for it. Mars is the unloved god in most charts too: the part of you that was scolded for its heat, that fights clumsily because no one welcomed its first fights. The myth's promise is precise — Mars served consciously, like Cadmus serving his eight years, fathers Harmonia; Mars rejected fathers Fear and Terror. His sign shows how your will converts to action; his aspects show whether the blade has been aimed or is still cutting its owner.","mundane":"The military, war, violent crime, political unrest — and the men of the nation, the men's vote. Mars ANGULAR (1st, 4th, 7th, 10th) is the classic war warning; Mars in the 7th under any condition can presage war. Well dignified, he turns reformer: bad officials removed, real prosecutions, hard changes for the better.","actor":"the military, the men of the nation","orrery_summary":"To Energize · Military, conflict, and the men of the nation. War, force, aggression, unrest, and the national capacity to act; angular Mars heightens the warning, while a well-conditioned Mars can force reform and remove bad officials."},"Jupiter":{"myth":"Hidden in a cave and raised on goat's milk, Zeus grew strong enough to depose old Kronos — but he did not repeat his father's deed: he made him disgorge the swallowed children, freed the fettered prisoners, and won his war with the help of the very monsters Uranus had buried. He swallowed Wisdom herself so that she would think within him, and then divided the world so that every power — even hateful Mars — received its prerogative and honor. Change and meaning are his essence.","natal":"To Expand and Affirm — Faith, the Courage to Hope, the power of saying Yes. Jupiter shows where life is generous with you and where you are asked to be generous back; where meaning comes easily, and excess comes easier. The myth is the instruction: he wins not by repeating the father's repression but by freeing what was swallowed and buried — your Jupiter grows by liberating the exiled parts and giving every inner power its prerogative and honor, hateful ones included. Where he stands, the world-order in you is renegotiated toward largeness.","mundane":"Every hierarchy that grows — corporations above all, plus courts, judges, clergy, charities. The economic barometer: watch Jupiter for the nation's material condition. Dignified: peace, order, profit. Poorly placed: stagnation and corruption — problems ignored while they are still small enough to manage.","actor":"corporations, courts, the growing hierarchy","orrery_summary":"To Expand & Affirm · Corporations, courts, and growing hierarchies. Law, religion, wealth, and alliances; an economic barometer whose expansion can produce peace, order, and profit — or excess, avoidance, stagnation, and corruption."},"Saturn":{"myth":"Kronos took the flint sickle and cut Heaven from Earth, ending the timeless abundance and beginning measured time — then ruled alone, in fear, swallowing his own children until a swaddled stone deceived him. Deposed at last, the old tyrant was given stony Latium, and taught humankind agriculture: the devourer became the harvester. Even if we cast him behind us, he still gazes at us from the natal chart — and given his territory, he yields, in the end, rich harvest.","natal":"Kronos, the Stern Father — Structure, Limits, Dignity, Self-Respect. Nature = to Endure. Saturn gives the Ability to do What You do Not Feel like Doing, and pays in the only currency that lasts: Solace in Hard Work, Sustained Effort Over Time. But read his whole story, not just the sickle: the god who cut life into measured time and devoured his own children ends as the teacher of agriculture — the devourer becomes the harvester when he is finally given his own stony ground. Where Saturn stands, give him territory instead of exile; what he takes early he returns with interest, late and real.","mundane":"Hard facts, hard knocks, and the things that endure: the establishment, the bureaucracy, institutional inertia. Dignified: stability and calm — prosperity through wise management, not growth. Debilitated: the unwanted consequences of past behavior arrive; negative Saturn brings more grief than almost anything else in a mundane chart.","actor":"the establishment, the bureaucracy","orrery_summary":"To Endure · Establishment and bureaucracy. Structure, authority, restriction, and institutional inertia; well-conditioned Saturn stabilizes through discipline and wise management, while an impaired Saturn brings accumulated consequences home."},"Uranus":{"myth":"The starry sky covered the Earth completely, and their children were too many and too monstrous — hundred-handed, fifty-headed — so Uranus pushed them back into the depths and would not let them into the light. He is the creative excess that can only be known by its effects: the bolt from the unknown, the idea that comes when it pleases and stays away when it pleases. The new, the departure, the future — even if it terrifies.","natal":"Prometheus and old Ouranos at once — the Awakener. Breakthroughs, Liberation, Absolute Truth, the Individualist. The myth cuts deeper than the rebel cliché: Uranus is the creative excess so prolific it frightens even its maker, who buries the hundred-handed children rather than let them into the light — and the buried ones always return, as lightning, as the idea that arrives on its own schedule. Where Uranus stands, the script you inherited will not hold, and what you refuse to let into the light will burst its container; the work is to midwife the monstrous-new instead of burying it.","mundane":"The individual against the mass: democracy, countercultures, revolution — and the machines that run without us: factories, computers, the internet (Mercury rules tools needing human skill; Uranus rules automation). Dignified: constructive reform and national success. Debilitated: crises, failed reforms, shocking events that seize the imagination.","actor":"the people-as-individuals, technology, the counterculture","orrery_summary":"To Awaken · Individuals, technology, and counterculture. Revolution, disruption, automation, and sudden reform; it can liberate and renew, or shock and destabilize when reform breaks down."},"Neptune":{"myth":"Three paces take Poseidon from Olympus to his castle at the bottom of the sea; the waters open joyfully when he comes, and his trident can raise the storm or lay the fog of forgetfulness. Into his waters fell heaven's lost creative power, and Venus grew from the foam. He saves mariners or draws them under — dissolving the boundaries of the ego into ecstasy, deception, or the dream that carries us.","natal":"Dissolution and the Ideal — the Oceanic Depths of the Unconscious, the Window Beyond the Ego. Neptune is the longing for what the world cannot supply: Transcendence, Mysticism, Visionary Imagination — and their shadows, Delusion and Escapism, drawn from the same water. Remember what lives in his sea: the lost creative power of heaven fell there, and Venus grew from it — what dissolves in you is not destroyed, it is being readied for a birth you cannot schedule. His condition shows whether you sail his waters, are carried by them, or go under.","mundane":"Almost always malefic in a mundane chart — the hardest-won rule in the toolkit. Neptune is unity, from the divine to the mob, and politics is rarely kind to unities: mass movements, propaganda, speculative bubbles, scandal, dissolution. Only completely unafflicted does he favor democracy and peace. Sun–Neptune hostile is the single most dangerous aspect in mundane work. Debilitated in the 6th or 8th: pandemic warning.","actor":"mass movements, propaganda, the collective mood","orrery_summary":"To Dissolve & Idealize · Mass movements, propaganda, and collective mood. Unity, sea and oil, bubbles, scandal, and glamour; mundane Neptune is shadow-heavy and should be treated cautiously unless completely unafflicted."},"Pluto":{"myth":"Hades means 'the invisible': the oldest brother, who set foot on earth only once — to seize Persephone — and rules the depth where night, sleep, and death keep house, and where the morning sets forth. When people learned to see the riches under the earth, they gave him a new name and the horn of plenty. He is the seed's law: the form must perish in the dark before it grows into the light — in Pluto we find the end, or the abundance, of life.","natal":"God of the Underworld — Resurrection, Power Struggles, Overwhelming and Catastrophic Extremes. Ever-Evolving, Transformative, pure Intensity. His two names are the whole teaching: Hades, the invisible one who takes; Pluto, the wealth-giver with the horn of plenty — the same god, before and after humankind learned to see riches in the dark. Where he stands you do not negotiate, you descend: the form must perish in the dark before it grows into the light, and what comes back up carries the abundance. The morning sets forth from his house.","mundane":"Collective power as raw force — purgation, destruction-and-rebirth, the compulsive imposition of mass will. Handle with healthy skepticism: Pluto invites projection more than any other planet, and many predicted catastrophes never came; keep him in the chart but stay grounded in actual data. In this chronicle he carries the Aquarius signature: the underworld struggle over what the new human being will be.","actor":"the masses-as-force, collective power","orrery_summary":"To Transform & Purge · Masses-as-force and collective power. Purgation, coercive transformation, destruction, and rebirth; keep the reading tied to actual evidence because Pluto invites projection more readily than any other planet."}},"signs":{"Aries":{"text":"The vernal equinox — 'the conclusive victory of light.' The ram here is the WILD mountain ram, quick and daring, fighting to a definitive end, victory or defeat — never the dull domestic sheep. Primal, Raw Strength, Survival Instinct, Life Choosing Existence Over Surrender and Extinction: Aries imagined as leaping is the symbol of life arising anew, and it asks permission of no one. Its tender secret: beneath the wildness runs the Mars-and-Venus longing to be fully accepted in spite of — indeed WITH — all one's wildness. Shadow: ruthlessness, losing one's head, the rage that turns inward when it finds no field.","mundane":"A nation's affairs in Aries run hot and fast: initiative, confrontation, the survival reflex. Things BEGIN here — wars included."},"Taurus":{"text":"The bull of every ancient fertility religion — the Nile flood was 'the gift of the bull' — yin despite the horns, with the Moon exalted in her. Quality, the Five Senses, the Natural Habitat: peaceable, slow, sure-footed, enjoying, seeking out the tastiest and chewing it twice. Give Taurus time, psychically and physically, and he reaches the goal in his own good time — and the fruit he harvests is fully ripe. Provoked past his patience, his blind rage knows no limits, exactly like slighted Venus. Shadow in three words: Having overpowers being.","mundane":"Money, land, food, the tangible economy. Affairs in Taurus concern what the nation owns and refuses to give up; change arrives slowly and is resisted hard."},"Gemini":{"text":"The first human figures in the zodiac — Castor and Pollux, one mortal, one immortal, whose love made Zeus let them alternate between Olympus and the underworld: the only beings at home in both worlds. Endless Learning, the Eternal Quest for Information, Duality, Openness to the Unexpected — as though the Gemini always have four eyes and four hands at their disposal. The task is Heraclitus's motto: the path downward and the path upward are together one path — the two snakes on Hermes's own staff. Shadow: fragmentation, the perpetual mobility that tarries nowhere.","mundane":"The information field itself: press, debate, networks, the doubled story. The United States is classically ruled by Gemini — affairs here go to the national conversation and its forks."},"Cancer":{"text":"The solstice — the zenith that is simultaneously the beginning of descent. The Great Mother, Nurturing, Protective, a Safe and Restorative Home, Raw Direct Emotion — and the crab's hard teaching: to grow at all it must repeatedly slough its shell, and while the shell is off, it is utterly without armor. Again and again it must surrender its armor and accept suffering, or growth and transformation are not possible. Antennae for every psychic movement; pincers that won't let go; the Acceptance of Human Frailty as a daily practice. Shadow: anxiousness dressed as modesty, solicitude that is secretly self-help.","mundane":"Homeland, housing, food security, the protective instinct of the nation — borders as a mother's arms or a fortress wall."},"Leo":{"text":"The solar animal — the all-seeing eye that never closes, Regulus the regal star at the heart. The Urge to be Seen and Celebrated; Attention is a life-giver; self-assurance taken completely for granted, territory precisely staked, the Emotional Risk of Authentic Self-expression accepted daily because the heart leads or nothing does. The warning is structural: Leo and Sun together form a never-extinguished consciousness, so the dark side cannot be seen even by Leo himself — whatever he is unwilling to see, he does not see. Shadow: vanity, hedonism concealing the fear of death, too proud to spare himself, to the point of heart failure.","mundane":"Spectacle, sovereignty, the stage of power: the leader as performer, the nation's pride and its theater. Faith in the seen self."},"Virgo":{"text":"Harvest-time, the virgin with the ear of grain — not Athena but Demeter and Kore, the mystery shown at Eleusis where a head of grain held aloft meant: the one is the other, this is you, this is me. The head of grain contains both fruit and seed — harvest of what has been, seed for future life: Breaking Things Into Components, Editing, Processes, the Comparison of the Ideal to the Actual, all in service of that double trust. Her virginity is gathered, consciously administered power; her reserve is not coldness but emotional economy. Shadow: compulsive perfection and pedantry, concealing a suppressed wish to be seized by deep experience — the Persephone-descent that still awaits her.","mundane":"The civil machinery: administration, public health, labor, logistics — the audit of the ideal against the actual. Reform by checklist."},"Libra":{"text":"The autumn equinox, but the scales are older than the calendar — they are the scales of fate: Anubis weighed the heart of the deceased against the feather of truth, and the heart had to be neither too light nor too heavy. The soul must be in balance with its inner truth — that is Libra's real work, beneath Balance, Diplomacy, Making Peace with Paradox, Perceptual Intelligence. Harmony here is attained ever and again, never owned, which is why the famous equanimity is labile. Most of all Libra loves to say yes; refusals come hard, late, if possible by phone, and always in friendly terms. Shadow: avoidance called peaceableness, composure that is really withdrawal from feeling.","mundane":"Treaties, alliances, courts, open enemies — the architecture of balance between powers. Affairs here are settled at the table or not at all."},"Scorpio":{"text":"Dying nature with the winter seed already sown: while the old dies, new germinations are being prepared. Focused Mars — the Detective, Unflinching Insight, Psychological Truth, the Raw Reality of Life — because in this sign it is a question of a battle between life and death, a battle to reclaim life from death. Goethe, born with Scorpio rising, named its weather: exulting to heaven, depressed to death. Its great star is Antares, 'contra Mars' — the deadly side of Mars made necessary so that the countervailing force of new life is possible. Shadow: the ever-ready stinger, analyzing instead of loving, fighting in the world the enemy — or the god — in himself. Resolved, he is the wounded healer.","mundane":"The hidden ledger: intelligence, debt, other people's money, purges, what power does in the dark. Washington D.C. is classically Scorpio's city."},"Sagittarius":{"text":"The darkest weeks of the year — and the first hope of new light begins precisely in the deepest darkness. The centaur is Chiron, not the brawling kind: Saturn's son, the friendly healer and teacher of heroes, who gave away his immortality to Prometheus the fire-bringer. Three realms in one figure — animal, human, transcendent: the bow of Sagittarius embraces heaven, earth, and its depths, and its goal lies in the distance, in the stars. The Philosopher, the Voyager, Natural Law; Truth is More Important Than Facts. Shadow: the preacher who hasn't lived it — the thinner his own experience, the more threadbare and fanatical the missionary zeal.","mundane":"Belief at national scale: religion, higher law, the courts of final appeal, the foreign horizon, the story a nation tells about its destiny."},"Capricorn":{"text":"The winter solstice, the return of the light: it was not Olympian abundance but Saturnine parsimony that governed at the birth of the divine child, and Zeus himself began hidden in a cave, fed on goat's milk. The mountain goat above the snowline: the Aim of Becoming an Elder, Self-discipline, Absolute Mastery, Integrity, the cold clear eye on reality. Capricorn translates intention into action not because he wills it — that would be Leo's way — but because it has to be that way; If You Cut Corners, the Corners Will Cut You. The knee he rules can stride boldly or kneel: at the Saturnalia masters served slaves, because all alike serve a higher meaning. He loves the heights and does not find the hard life up there hard — to him, the grasses are not sparse. Shadow: the old pre-Jupiter Saturn — moral narrowness, power lust, isolation.","mundane":"The state itself: government as structure, the establishment's spine, executive authority in its institutional form. What endures — and what calcifies."},"Aquarius":{"text":"Deep winter; life moves indoors and inward, and the water bearer pours out his gathered vessel as a stream of stars — the human being fully upright, tipping out experience to pass it on and so effect something new. The Paradigm Shifter, A New Type of Human Being, the Process of Individuation, Free-thinking — under the Uranus myth replayed as an ethic: the children of Uranus can no longer be left in caves; they must be seen and handed on, or they will autonomously burst the bonds of fearful constriction. On the Outside Looking In, Utopian and Dystopian at once, paying for the wide view with Alienation. Shadow: the giver who cannot take, detachment become indifference, love rationed lest freedom be lost — and the warning of Antaeus, invincible only while touching the Earth.","mundane":"The collective future: legislatures, networks, ideology, the masses organized by idea rather than blood. Russia's classical sign; in this era, Pluto's stage."},"Pisces":{"text":"The last sign — the ice melts, all that is hard yields to the soft element. Two fish bound together yet swimming back to back, unable to look each other in the eye: meaningful devotion and self-surrender alternating in one soul. The Ocean of Consciousness, Primal Oneness with the Universe, Visionary Imagination, the Realm of Archetypal Patterns — with the fish's sense for every tremor and current, and the fish's peril: Pisceans are easily washed away; every large wave carries them a distance before they even perceive it. Enlightenment and Escapism drink from the same well. Shadow: lack of self called self-sacrifice, symbiosis called love, suffering cultivated as strength. Fulfilled, they are as alive as a fish in water.","mundane":"The dissolved collective: faith, oil and the sea, hospitals and prisons, propaganda's fog, the national unconscious. What cannot be measured but moves everything."}},"houses":{"1":{"natal":"The vessel itself — your body, temperament, the angle at which you meet the world. The rising sign is the costume the soul chose for this play; planets here are stitched into your presence. The first house always carries an Aries quality — Vita, life arising.","mundane":"The ordinary people of the nation — their condition, health, morale, and attitudes. The sign on the 1st is the national myth in force; the 1st-ruler is the people's significator (watch its dialogue with the Moon's political class)."},"2":{"natal":"What you have and what you're worth to yourself — resources, talents, the security that lets you act. Lucrum: value as a verb.","mundane":"The economy: money, banks, currency, national revenue, financial markets — and the nation's values made visible in its ledgers."},"3":{"natal":"The near world — siblings, neighbors, daily errands of the mind: language, learning, the thousand small messages that weave a life. Fratres.","mundane":"Communications and the press, transport, schools, the internet's pipes, neighboring countries. Where the national conversation physically lives."},"4":{"natal":"The taproot — home, family, ancestry, the private ground you stand on. Genitor: the parent carried within. Adult Life: the Home Each Person Creates for Themselves. Endings return here.","mundane":"The party OUT of power — the opposition — plus the land itself: agriculture, mining, real estate, the rural population, the nation's foundations."},"5":{"natal":"The fire of play — creativity, romance, children, the joy that needs no justification. What you make for the love of making.","mundane":"Entertainment, sport, speculation and the stock casino, celebrities, the birth rate — and the upper house of the legislature."},"6":{"natal":"The daily practice — work, health, service, the disciplines that keep body and life in working order. Devotion in overalls.","mundane":"Workers and unions, the civil service, public health and epidemics, and the armed forces as institution — the nation in service uniform."},"7":{"natal":"The Other — partnership, marriage, the open adversary; every mirror you contract with. What you disown in yourself arrives here wearing someone else's face.","mundane":"Foreign affairs and policy, political treaties (NOT trade treaties), international incidents, open enemies — peace, war, and power politics at the table."},"8":{"natal":"The shared depths — other people's resources, debt, intimacy, death-and-rebirth. What must be surrendered to be transformed.","mundane":"International finance and foreign investment, taxes, insurance, the national death rate — the nation's death-and-rebirth ledger."},"9":{"natal":"The far horizon — philosophy, faith, higher learning, the long journey that turns experience into meaning.","mundane":"The judiciary and higher courts, religion, universities, publishing, long-distance travel and the air — where the nation reasons about ultimate things."},"10":{"natal":"The summit in public view — vocation, authority, the Achievement your name gets attached to. What you build where everyone can see it.","mundane":"The government and party IN power, the Executive Branch, the head of state, national prestige — the Power and Authority of the Gov't and the Nation as a Whole."},"11":{"natal":"The chosen tribe — friends, allies, collective hopes; the future you build with others who share your stars.","mundane":"The legislature (especially the lower house), local government, allied nations, and the collective hopes and ideals of the age."},"12":{"natal":"The hidden harbor — solitude, the unconscious, self-undoing and self-release; Addictions and angels share this address. What dissolves you can also deliver you.","mundane":"The hidden state: prisons, hospitals, asylums, intelligence agencies, secret societies, subversion, espionage — the nation's self-undoing and its shadows."}},"aspects":{"conjunction":{"dyn":"Direct Blending Initiates Pure Activity — co-presence, two principles fused into one voice. Nothing mediates: the planets must act together whether their natures agree or not, like two gods sharing one body for the duration.","mundane":"In mundane work the conjunction takes the color of its planets: a seed-moment, the start of a new cycle between these two actors. With malefics or Neptune it counts as hostile.","kind":"neutral"},"opposition":{"dyn":"Externalizes through relationship and projection — full face-to-face awareness of both functions. The harvest point of the cycle: what was seeded at the conjunction stands revealed, often wearing an opponent's face. Well integrated, the two enhance each other.","mundane":"The harvest and the confrontation: the matter seeded at the conjunction comes to a head between these two actors. Hostile.","kind":"hostile"},"square":{"dyn":"Crisis-oriented — purposeful turning-points in consciousness. Internalized tension demanding decisive action; it agitates, pressures, goads to achieve. Self-blocking only when its challenge is denied.","mundane":"The crisis quarter: friction between these actors forces events. Squares are when the storyline stops being deniable.","kind":"hostile"},"trine":{"dyn":"The line of least resistance — harmony, relaxation, pleasurable reception. The gift that asks nothing, which is both its grace and its danger: unearned ease can go passive.","mundane":"Help that flows without effort between these actors — fortunate, stabilizing, occasionally complacent.","kind":"helpful"},"sextile":{"dyn":"Opportunity through active, willing cooperation — the aspect of the open door that still must be walked through. Curiosity seeking constructive synthesis.","mundane":"A workable opening between these actors — fortunate where someone has the wit to use it.","kind":"helpful"},"quincunx":{"dyn":"The nagging, almost-fated adjustment — re-assemble and correct. Two functions with no common ground forced to share a household; analyze, dissect, adapt.","mundane":"An awkward, chronic misalignment between these actors — recurring irritation that demands adjustment rather than resolution.","kind":"hostile-minor"},"semi-sextile":{"dyn":"The next-door aspect — quiet growth by adjacency. Resources passed over the fence between neighboring signs; subtle, cumulative, easy to miss.","mundane":"A minor channel of aid between these actors — background support.","kind":"helpful-minor"},"semi-square":{"dyn":"Internal friction below the threshold of crisis — the grind that precedes the square's open turning-point. Irritation that builds skill or temper.","mundane":"Low-grade friction between these actors — chafing that precedes open conflict.","kind":"hostile-minor"},"sesqui-square":{"dyn":"Friction on the far side of the opposition's mirror — agitation in the established order of things, demanding correction of what was over-extended.","mundane":"Aggravation in an already-public matter between these actors.","kind":"hostile-minor"},"quintile":{"dyn":"The creative fifth-harmonic — the gift of making: pattern-mastery, the talented hand. What these planets build together is signed work.","mundane":"A signature of distinctive craft or stratagem between these actors — talent applied, sometimes cunning.","kind":"creative"},"septile":{"dyn":"The seventh-harmonic — the fated, the set-apart, an explorative aspect eager for new experience that follows its own non-rational clock.","mundane":"An odd, fate-flavored linkage between these actors — events that feel appointed rather than caused.","kind":"subtle"},"novile":{"dyn":"The ninth-harmonic — gestational: an aspect of rebirth based upon meaning, the Ability to See Meaning in Everything quietly maturing toward birth.","mundane":"A slow inward ripening between these actors — visible only at delivery.","kind":"subtle"},"undecagon":{"dyn":"The eleventh-harmonic — the remainder that won't divide evenly: obsessive, irrational, generative at the edge of pattern.","mundane":"An irrational-number linkage — background strangeness between these actors.","kind":"subtle"}},"texture":{"applying":"Applying — the aspect is still forming: the matter is building, the pressure rising toward exact. Events tend to land at or just before perfection.","separating":"Separating — the perfection is past: the matter is already in motion, its consequences unwinding. The event happened; this is the wake. Actually initiates the waning aspect cycle when separating.","upper":"Upper (waning) — past the opposition in the pair's cycle: consciousness phase. The matter is being understood, distilled, and reoriented toward the next seed; what was built is now examined.","lower":"Lower (waxing) — between conjunction and opposition: action phase. The matter is being built outward into form, instinctively, before it fully knows itself.","dissociate":"Dissociate (out-of-sign) — the aspect crosses a sign boundary, so the angle is real but the sign-logic is dislocated: the two speak the aspect's geometry with mismatched grammars. Subtler, stranger, easy to underrate."},"dignity_text":{"rulership":"in rulership — at home, fully resourced; the planet acts with its whole vocabulary","exaltation":"exalted — an honored guest; the planet performs above itself, sometimes theatrically","detriment":"in detriment — exiled opposite its home; the planet must improvise with borrowed tools","fall":"in fall — depressed below its station; the planet's gifts are discounted and must be proven twice","peregrine":"peregrine — a wanderer with no essential dignity; the planet drifts toward whoever disposes it"},"synods":{"Neptune-Pluto":{"years":"~492 yr","text":"Whole epochs of civilization — the era's deepest spiritual ideals and aspirations. Conjunctions seed great cultural ages; everything else is commentary on the standing seed (1891–92, late Gemini)."},"Uranus-Neptune":{"years":"~172 yr","text":"Civilization's unfoldment through capital (Uranus) against labour (Neptune) — conservatism and liberalism, industrialization, the machinery of mass ideals. Helpful contact between them is among the five most fortunate in any mundane chart: political class and people in constructive reform."},"Uranus-Pluto":{"years":"~127 yr","text":"Radical restructuring of peoples and nations — building again on the ruins of the old. The 1965–66 conjunction seeded the computer age; its squares and trines time the demolition-and-rebuild work."},"Saturn-Uranus":{"years":"~45 yr","text":"The politics of Order — conservative-authoritarian consolidation, imperialism, heavy capital; a strong Middle-East signature. Old structure versus the lightning."},"Saturn-Neptune":{"years":"~36 yr","text":"The paramount cycle of national life: socialism and idealism — the dissolution (Neptune) of whatever has become negatively crystallized (Saturn), and the descent of new collective images. The chronicle's defining synod, conjoining in Aries."},"Saturn-Pluto":{"years":"~33 yr","text":"Emerging nations, deep purgation, resurrections — back-to-basics severity, black-and-white thinking, compulsive collective power. The square is a crisis of authority."},"Jupiter-Saturn":{"years":"~20 yr","text":"The Great Chronocrators — the ground-base of social structure and national identity. Element mutations mark civilizational reorientation: 1603 Fire, 1842 Earth, and now the Air age (~2020–2060)."}},"rankings":{"dangerous":[{"pair":"Sun-Neptune","rank":1,"text":"Far and away the most unfortunate indication in a mundane chart — something in the nature of a downfall or collapse. Scandal, confusion, the government's ground dissolving."},{"pair":"Sun-Saturn","rank":2,"text":"Loss of power, obstacles, economic stagnation, public-health dangers — the executive ground down by hard facts."},{"pair":"Sun-Mars","rank":3,"text":"Conflict and belligerent passions — partisan hatred, violence against officials, lost battles."},{"pair":"Mars-Saturn","rank":4,"text":"Public discontent, rioting, crimes against authority — the government loses support in the streets."},{"pair":"Moon-Saturn","rank":5,"text":"Misfortune to the political class and the country — economy depressed, government may collapse."}],"fortunate":[{"pair":"Sun-Jupiter","rank":1,"text":"The most favorable aspect in mundane astrology — peace, prosperity, good luck for the government."},{"pair":"Venus-Jupiter","rank":2,"text":"One of the best aspects in any mundane chart — peace, goodwill, prosperity, quarrels settled."},{"pair":"Moon-Jupiter","rank":3,"text":"Peace and prosperity — the economy expands, the political class in clover."},{"pair":"Sun-Moon","rank":4,"text":"Harmony between government and political class — prosperity through alignment."},{"pair":"Uranus-Neptune","rank":5,"text":"Harmony between the political class and the people — constructive reform."}]},"moon_phases":{"new":"New Moon — the seed: a nine-month storyline begins here, mostly invisible. Whatever is conceived now will take its first visible step at the First Quarter ~9 months on. In mundane timing, compare to the governing ingress: a lunation on ingress positions is the minute-hand striking the hour.","first_quarter":"First Quarter — the planted seed breaks ground: the storyline conceived ~9 months ago takes visible action; crisis of action, building against resistance.","full":"Full Moon — fruition and revelation: the matter seeded ~18 months ago stands fully lit, relationships and consequences exposed. The harvest of its Moon Family line.","last_quarter":"Last Quarter — release and distribution: the ~27-month storyline gives back its yield and clears the field; crisis of consciousness, the letting-go that makes room for the next seed.","eclipse_amp":"Eclipse amplification — an eclipsed lunation is the same phase with the volume turned far up and the timeline stretched: a solar eclipse acts for as many YEARS as it lasts in hours, a lunar eclipse for as many MONTHS. The old empirical rule: a solar eclipse path over a populated region brings that region a disaster within months, shown by house."},"points":{"ASC":{"natal":"The Ascendant — the meeting-edge of self and world: your arrival style, the body's first language. Planets here are announced before you speak.","mundane":"The rising sign and its ruler ARE the people — give the angles pride of place: what touches the ASC can be released into the world."},"MC":{"natal":"The Midheaven — what is culminating: public standing, the visible summit of the life. In Whole Sign it remains a sensitive POINT and may fall in the 9th, 10th, or 11th — that house placement is the story.","mundane":"The culminating degree — the government's public face. Angular planets here show what the period is FOR; tight aspects to the MC time the headline."},"NN":{"natal":"The Moon's North Node — the hungry direction: unfamiliar territory the life is being pulled toward. Appetite, not yet skill.","mundane":"The collective's growth edge — where the nation is being drawn, eclipses marking the curriculum."},"SN":{"natal":"The Moon's South Node — the inherited fluency: mastered, comfortable, and overspent. The gift that becomes a rut.","mundane":"The collective's old habit — what the nation reaches for under stress, and must spend down. Eclipses here audit the past."}},"f250_signatures":{"pluto_aquarius":"Pluto in Aquarius → Resurrection / Power Struggles / Overwhelming & Catastrophic Extremes in Paradigm Shifter / A New Type of Human Being / Process of Individuation → a catastrophic, underworld power-struggle over what the new human being will be.","saturn_neptune_aries":"Saturn–Neptune in Aries → Structure / Limits / Endure meeting Dissolution / the Ideal / Utopian Social Ideologies in Primal / Survival Instinct / 'Life Choosing Existence Over Surrender and Extinction' → enduring structure dissolved into a raw, survival-driven new ideal.","uranus_gemini":"Uranus in Gemini → Prometheus / Awakener / Breakthroughs / Liberation in Endless Learning / Eternal Quest for Information / Duality → the Promethean awakening — and doubling — of information itself.","jupiter_leo":"Jupiter in Leo → Expand & Affirm / Faith / Courage to Hope in Urge to be Seen / 'Attention is a life-giver' / Spontaneous Self-expression → faith in spectacle; affirmation of the sovereign, seen self."}},"pairs":{"Jupiter-Neptune":{"pair":"Jupiter–Neptune","cycle":"~13 years","current":"Square June 2025, Trine November 2025","prev":"April 2022 in Pisces","helpful":null,"hostile":"Under hostile aspects, Jupiter-Neptune produces \"confusion, misunderstanding, charges of bad faith; conflict between political class and masses; conspiracy theories flourish\" (the tradition). The hierarchy's promises to the people ring hollow. Religious and nonprofit institutions face accusations of hypocrisy. The political class and the masses talk past each other — both convinced the other acts in bad faith. Conspiracy theories proliferate because Neptune's fog obscures Jupiter's institutional workings, and the people fill the gap with suspicion. the old cycle-school adds that the hard aspects bring sectarian conflict and inflationary bubbles — faith inflated beyond all rational proportion.","trigger":null,"current_text":"The 2022 Pisces conjunction (Neptune's home sign) seeded maximum idealism — the hierarchy's promise to the collective was cast in Neptune's strongest possible terms. The 2025 square = the ideal hits reality; hierarchical organizations face the masses' disillusionment. The trine later in 2025 = the ideal finds constructive expression; humanitarian movements and charitable organizations gain traction.","text":["the old cycle-school links Jupiter-Neptune strongly to idealistic and socialist economies and to France specifically. It is the cycle of faith meeting the collective dream — humanitarian, religious, utopian. When the hierarchy (Jupiter) encounters the dissolving tide of mass sentiment (Neptune), the result is either genuine humanitarian progress or \"pie in the sky\" that collapses into inflation, sectarian quarrels, and fighting for ideals that were never grounded in reality. The hard aspects historically precipitate rampant inflation when not well earthed.","the tradition's delineation sharpens the mundane picture. Under helpful aspects, Jupiter-Neptune brings \"peace and goodwill; benefits the people, especially the unfortunate/disadvantaged; humanitarian movements succeed; disputes find peaceful settlement.\" Hierarchical organizations — government, nonprofit, religious — turn their institutional power toward the collective welfare. Courts settle disputes with wisdom. Charitable organizations achieve real impact. The disadvantaged benefit because Jupiter's hierarchy serves Neptune's popular causes rather than exploiting them."],"arcs":[],"note":"03 - Astrology/Interpretations/Jupiter–Neptune.md"},"Jupiter-Pluto":{"pair":"Jupiter–Pluto","cycle":"~12 years","current":"Quincunx June 2025, Opposition July 2026","prev":"November 2020 in Capricorn","helpful":null,"hostile":null,"trigger":null,"current_text":"The 2020 Capricorn conjunction (alongside Saturn-Pluto) = pandemic power consolidation. Hierarchical organizations — governments, corporations, international bodies — concentrated unprecedented power under emergency conditions. The July 2026 opposition = the full moon of this cycle. Whatever power was concentrated in 2020 now faces its reckoning: the corporate sector, the courts, and the political hierarchy must account for what they did with the authority they seized.","text":["Jupiter-Pluto is the cycle of hierarchical and corporate power confronting transformative and plutocratic forces — the attainment of power of all kinds, physical, material, mental, spiritual. the old cycle-school links it to international terrorism and the growth of plutocratic influence. When Jupiter amplifies Pluto, the hidden power structures that operate beneath the visible hierarchy expand: billionaire influence, intelligence agencies, organized crime, and the masses-as-force all grow stronger. The corporate sector and the plutocratic underworld become harder to distinguish.","the tradition offers no specific delineation for Jupiter-Pluto — Pluto was outside his framework — but the mundane logic follows from his Jupiter principles. Under helpful aspects, hierarchical organizations undergo constructive transformation: corporate reform succeeds, courts confront entrenched power effectively, religious institutions engage genuine spiritual renewal. The masses-as-force work through institutional channels rather than against them. Under hostile aspects, the hierarchy serves plutocratic interests — corporate monopoly expands, courts protect the powerful, religious institutions become vehicles for control rather than transcendence. International terrorism and organized crime (the old cycle-school's specific correlations) gain institutional sophistication. The Pluto caveat applies throughout: these delineations carry less empirical weight than the traditional-planet pairs."],"arcs":[],"note":"03 - Astrology/Interpretations/Jupiter–Pluto.md"},"Jupiter-Saturn":{"pair":"Jupiter–Saturn","cycle":"~20 years","current":"Square early 2025, Trine late 2025","prev":"December 2020 in Aquarius (Great Mutation into Air)","helpful":null,"hostile":null,"trigger":null,"current_text":"The first square (crisis/test) of what was seeded at the 2020 Great Mutation. The Air-era social structures — the digital economy, the information-based corporate order, the restructured federal bureaucracy — face their first real challenge. The national economy is tested; the government must prove it can manage the new order. The corporate sector's expansion meets the civil service's institutional resistance, and the legislature must arbitrate between them.","text":["the tradition: \"The Chronocrators — the Time Lords.\" The most fundamental social cycle in mundane astrology, governing the ground-base of the national economy, the corporate order, and the government's relationship to its own bureaucracy. Every 20 years, the corporate-expansive impulse (Jupiter) meets the bureaucratic-conservative impulse (Saturn) and the nation's social architecture is reset. The December 2020 conjunction in Aquarius was the Great Mutation — the first Air conjunction since 1186, shifting the element-basis of civilization from Earth (materialism, industry, land-based wealth, ~1842-2020) to Air (information, networks, ideas, digital wealth, ~2020-2220). the tradition's own \"Great Mutation\" element-shift framing confirms this reading.","the tradition's delineation for the pair is direct. Helpful Jupiter-Saturn aspects are \"very favorable for the national economy; wealth + hard work\" — the corporate sector and the civil service cooperate, the legislature passes sound economic legislation, the executive branch governs competently, and the laboring classes benefit from stable employment. Hostile Jupiter-Saturn aspects bring \"some form of economic trouble; the government faces difficulties\" — the national economy contracts or overheats, the corporate sector and the bureaucracy work at cross-purposes, and the executive branch struggles to maintain public confidence."],"arcs":[{"arc":"The Great Reckoning","note":"the old institutional order dissolving"},{"arc":"The Information War","note":"Air = information-based power structures"},{"arc":"Border & Homeland","note":"national identity in the Air age"},{"arc":"War Footing — Iran","note":"the Middle East powder keg and military posture"},{"arc":"Fringe, Disclosure & Health","note":"health freedom, disclosure, and institutional trust in science"},{"arc":"Great-Power Realignment","note":"the multipolar world taking shape"}],"note":"03 - Astrology/Interpretations/Jupiter–Saturn.md"},"Jupiter-Uranus":{"pair":"Jupiter–Uranus","cycle":"~14 years","current":"Semi-sextile June 2025 (early cycle)","prev":"April 2024 in Taurus","helpful":"Under helpful aspects (conjunction, sextile, trine), the tradition describes results \"favorable for constructive legislation; helpful reforms and new laws benefit society; strengthens party in power; peace, good government.\" The hierarchy reforms itself — legislation modernizes outdated structures, the courts embrace innovation, corporate organizations adopt new technologies. The party in power benefits because it is seen as the agent of progress. Democracy and the counterculture find their reforms codified into law. Machines, computers, and the internet expand under institutional support. It is the aspect of the reform that actually works.","hostile":"Under hostile aspects (square, opposition), the tradition warns that \"new laws cause more problems than they solve; reforms prove unworkable; unfortunate for party in power; in wartime, defeat likely.\" The hierarchy attempts to manage radical change and fails — legislation backfires, reforms destabilize rather than improve, the corporate sector's modernization efforts create chaos. The party in power is weakened because it is blamed for disruption it cannot control. Counterculture and democratic movements challenge institutional authority, and the institutions respond clumsily. the old cycle-school's war-mongering warning activates: in crisis periods, the hierarchy reaches for military force to control change it cannot absorb.","trigger":null,"current_text":"Early in a new cycle after the April 2024 Taurus conjunction. The practical (Taurus) revolution is just germinating — hierarchical organizations are beginning to integrate the technological and financial disruptions (crypto, AI, manufacturing reshoring) that this conjunction seeded. The early aspects will show whether the hierarchy absorbs the revolution constructively or resists it.","text":["the old cycle-school calls Jupiter-Uranus \"a most powerful agent for change and progress\" — and also warns of dangerous war-mongering potential in crisis periods. It is the cycle of hierarchy meeting radical change, strongly capitalist-oriented: free-market buoyancy, growth of consciousness, Promethean rebellion amplified through institutional channels. When Jupiter's hierarchical organizations encounter Uranus's democratic and technological disruption, the result is either constructive modernization or institutional crisis."],"arcs":[],"note":"03 - Astrology/Interpretations/Jupiter–Uranus.md"},"Mars-Jupiter":{"pair":"Mars–Jupiter","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (conjunction when well-placed, sextile, trine), Mars-Jupiter channels martial energy into organizational reform. the tradition describes \"constructive changes for organizations — government, corporate, nonprofit; reforms less difficult; resistance to needed change less effective.\" The military operates efficiently under clear hierarchical command. Courts act decisively. Corporate restructuring succeeds. Nonprofit organizations expand aggressively and effectively. The key insight is that Mars's force serves Jupiter's hierarchy — reform happens because the energy to push through resistance is available and the institutional framework to direct it is functioning.","hostile":"Under hostile aspects (square, opposition), the combination produces what the tradition calls \"crisis and turmoil for organizations; scandals and hostile criticism; proposed changes not well thought out; can warn of epidemics.\" Hierarchical organizations face aggressive challenges — the military overreaches, the courts provoke fury, corporate scandals erupt. Reforms are attempted with more force than wisdom and backfire. Religious institutions face hostile scrutiny. The epidemic warning is specific to Mars-Jupiter: Mars rules disease and Jupiter amplifies whatever it touches, so poorly-aspected Mars-Jupiter periods bear watching for public health crises.","trigger":"Mars-Jupiter aspects are fast-moving (days to a couple of weeks) and mark the specific moments when organizational reform, military expansion, or institutional scandal activate the broader outer-planet storylines.","current_text":null,"text":[],"arcs":[{"arc":"The Great Reckoning","note":"legal offensives, aggressive prosecutions"},{"arc":"The Monetary Reset","note":"bold economic action, market surges"},{"arc":"War Footing — Iran","note":"military expansion, aggressive diplomacy"}],"note":"03 - Astrology/Interpretations/Mars–Jupiter.md"},"Mars-Neptune":{"pair":"Mars–Neptune","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (conjunction when well-placed, sextile, trine), Mars-Neptune channels combative energy into popular causes. the tradition describes results \"fortunate for interests of the people; popular causes make headway; long-standing problems can be overcome.\" The military serves the people's interests rather than elite ones. Mass movements gain the energy to break through long-standing obstacles. Public health improves because Mars-as-surgeon works in service of Neptune's collective welfare. The fog lifts enough for decisive action on behalf of the disadvantaged.","hostile":"Under hostile aspects (square, opposition), Mars enters Neptune's fog and the result is confusion, scandal, and hidden menace. the tradition warns that \"interests of the people suffer; scandals attract public attention; much talk of secret crimes and conspiracies; unfortunate for public health; can indicate epidemic.\" This is the fog of war made literal — military operations are compromised by deception, intelligence failures, or covert action gone wrong. Scandals involving secret crimes dominate the news cycle. Conspiracy theories proliferate because the actual conspiracy (Mars acting in Neptune's shadows) is real enough to feed them. The epidemic warning is significant: Mars rules disease and Neptune rules mass contagion, making hostile Mars-Neptune aspects a traditional red flag for public health crises.","trigger":"Mars-Neptune aspects are fast-moving (days to a couple of weeks) and mark the specific moments when covert operations, public health scares, or scandal eruptions activate the broader outer-planet storylines.","current_text":null,"text":[],"arcs":[{"arc":"War Footing — Iran","note":"covert operations, fog of war"},{"arc":"The Great Reckoning","note":"scandal eruptions, hidden actions exposed"},{"arc":"Fringe, Disclosure & Health","note":"health crises, pharmaceutical conflict"}],"note":"03 - Astrology/Interpretations/Mars–Neptune.md"},"Mars-Pluto":{"pair":"Mars–Pluto","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":null,"hostile":"Under hostile aspects, the combination is one of the most volatile in the mundane toolkit. The military and enforcement apparatus either serves plutocratic interests at the expense of the people, or collides with plutocratic power in ways that produce extreme violence. Financial warfare — sanctions, asset seizures, economic weaponization — escalates. Power confrontations become existential rather than negotiable. The masses-as-force turn violent. The transformation Pluto demands is resisted with Martian force, and the resistance itself becomes destructive. The Pluto caveat applies throughout: these delineations carry less empirical weight than the traditional-planet pairs and should be treated accordingly.","trigger":"Mars-Pluto aspects are fast-moving (days to a couple of weeks) and mark the specific moments when enforcement confrontations, financial warfare, or power struggles activate the broader outer-planet storylines.","current_text":null,"text":["Mars-Pluto brings military and enforcement power face-to-face with transformative and plutocratic forces. the tradition offers no specific delineation for this pair — Pluto was outside his framework — but the mundane logic is straightforward from the old cycle-school and observed correlations. Under helpful aspects, the military and law enforcement operate as instruments of genuine transformation: corrupt power structures are dismantled, plutocratic influence is checked by force of law, and the masses-as-force are channeled into constructive confrontation with entrenched power. Enforcement actions succeed because they target the right structures."],"arcs":[{"arc":"War Footing — Iran","note":"total warfare, extreme force"},{"arc":"The Great Reckoning","note":"power confrontation, institutional destruction"},{"arc":"The Monetary Reset","note":"financial warfare, economic weaponization"}],"note":"03 - Astrology/Interpretations/Mars–Pluto.md"},"Mars-Saturn":{"pair":"Mars–Saturn","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":null,"hostile":"Under hostile aspects (square, opposition), the two malefics compound each other's worst qualities. the tradition's delineation is stark: \"public discontent with the existing order; anger and dissatisfaction drive turbulent events; risk of rioting and crimes against authority figures; government loses popularity.\" The establishment's rigidity (Saturn) meets the public's combative frustration (Mars) and the result is confrontation — protests, riots, strikes, crimes against officials. The government overreacts with harsh discipline, which only inflames the anger further. Military operations suffer from both excessive caution and reckless aggression. Industrial disputes turn bitter and protracted.","trigger":"Mars-Saturn aspects are fast-moving (days to a couple of weeks) and mark the specific moments when enforcement crackdowns, institutional friction, or public anger at the establishment activate the broader outer-planet storylines.","current_text":null,"text":["Mars-Saturn is one of the most consequential pairs in mundane astrology — both traditional malefics working together or against each other. Under helpful aspects (conjunction when well-placed, sextile, trine), the result is formidable: the tradition describes \"efficiency and constructive effort; benefits the executive power in every sphere; governments pursue goals more effectively.\" The military operates with disciplined precision. Law enforcement is effective without being brutal. Industrial output increases. The establishment channels Mars's energy into structured, lasting accomplishment. It is the aspect of the skilled general who wins through strategy rather than brute force."],"arcs":[{"arc":"War Footing — Iran","note":"military confrontation, harsh discipline"},{"arc":"Border & Homeland","note":"enforcement crackdowns, structural resistance"},{"arc":"The Great Reckoning","note":"legal battles, institutional friction"}],"note":"03 - Astrology/Interpretations/Mars–Saturn.md"},"Mars-Uranus":{"pair":"Mars–Uranus","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":null,"hostile":"Under hostile aspects (square, opposition), the same energy turns destructive. the tradition warns of a \"disruptive influence; unexpected crises; disputes amplified; quarrels ignited; turbulence and lawlessness; an important figure may die.\" This is the aspect of the sudden strike — cyberattacks, terrorist incidents, assassination attempts, revolutionary violence. Technology weaponized. Machines and factories become sites of conflict. Democratic movements turn violent. The \"important figure may die\" warning is specific and sobering — Mars-Uranus hostile aspects have historically correlated with sudden, violent deaths of public figures. Lawlessness spikes because Uranus rejects authority and Mars provides the force to act on that rejection.","trigger":"Mars-Uranus aspects are fast-moving (days to a couple of weeks) and mark the specific moments when sudden crises, technological disruption, or revolutionary violence activate the broader outer-planet storylines.","current_text":null,"text":["Mars-Uranus is the lightning strike of mundane astrology — sudden, powerful, and impossible to predict in its specifics. Under helpful aspects (conjunction when well-placed, sextile, trine), the tradition describes results \"very favorable for constructive change and beginnings; energy and success; legislation is successful.\" Revolutionary energy is channeled constructively. New technologies emerge with military precision. Counterculture movements gain decisive momentum. Legislation passes that actually changes things. The factories, computers, and internet infrastructure (Uranus) are energized by Mars's drive and the result is rapid, effective modernization."],"arcs":[{"arc":"War Footing — Iran","note":"sudden strikes, technological warfare"},{"arc":"The Information War","note":"cyberattacks, digital warfare"},{"arc":"The Great Reckoning","note":"explosive revelations, sudden legal action"}],"note":"03 - Astrology/Interpretations/Mars–Uranus.md"},"Mercury-Jupiter":{"pair":"Mercury–Jupiter","cycle":"fast (weeks to months)","current":"","prev":"","helpful":"Under helpful aspects (conjunction, sextile, trine), Mercury-Jupiter is one of the most broadly positive combinations for the nation's economic and intellectual life. the tradition describes it as \"favorable for every department of the economy; prosperity increases; favorable for new legislation.\" The media carries good news because there is good news to carry. Trade and commerce expand. New legislation passes and is well-received. The courts communicate clearly. The press covers institutional reform fairly. Intellectual life flourishes because Jupiter's expansive faith meets Mercury's capacity for articulation — big ideas find their voice.","hostile":"Under hostile aspects (square, opposition), Jupiter's amplification distorts Mercury's information function. the tradition warns of \"unexpected economic difficulties; rising prices in stock markets may drop even faster than they rose.\" The media over-hypes, the markets over-extend, and the correction is sharper than the rally. Legislation is poorly drafted or poorly communicated. The press amplifies institutional scandals. Trade agreements collapse under scrutiny. The national conversation becomes grandiose and detached from reality — talking heads promise what hierarchical organizations cannot deliver, and the gap between rhetoric and results produces backlash.","trigger":"Mercury-Jupiter aspects are fast-moving (days to a couple of weeks) and mark the specific moments when economic optimism, legislative announcements, or media amplification activate the broader outer-planet storylines.","current_text":null,"text":[],"arcs":[{"arc":"The Information War","note":"media optimism, expansive messaging"},{"arc":"The Monetary Reset","note":"economic forecasts, trade announcements"},{"arc":"Great-Power Realignment","note":"diplomatic communications, summit talk"}],"note":"03 - Astrology/Interpretations/Mercury–Jupiter.md"},"Mercury-Mars":{"pair":"Mercury–Mars","cycle":"fast (weeks to months)","current":"","prev":"","helpful":"Under helpful aspects (conjunction, sextile, trine), Mercury-Mars is \"favorable for all Mercurial affairs,\" as the tradition puts it. \"Technological innovations favored; education, literary activities, sciences flourish.\" The national conversation is energized and productive. Media does investigative work rather than just generating heat. The transportation and communications sectors see real improvements — new technology deployed, infrastructure upgraded, scientific breakthroughs announced. Military communications function well. Education policy is pushed forward by decisive action rather than stalled by committee.","hostile":"Under hostile aspects (square, opposition), the combination becomes \"unfavorable for the communication and transport sector; strikes, protests, disturbances.\" Speech is weaponized. Media confrontations escalate past argument into something closer to combat. Transportation strikes or disruptions make headlines. Protests — especially those organized through media and communications channels — become heated and potentially violent. The sciences and education suffer from politicization. Military communications may be compromised or leak at the worst moment. Legal arguments turn into courtroom combat where rhetoric overwhelms reason.","trigger":"Mercury-Mars aspects are fast-moving (days to about two weeks) and mark the specific moments when aggressive communication, media conflict, or transportation disruptions activate whatever broader outer-planet storylines are in play.","current_text":null,"text":[],"arcs":[{"arc":"The Information War","note":"heated rhetoric, media confrontations"},{"arc":"War Footing — Iran","note":"military communications, threat messaging"},{"arc":"The Great Reckoning","note":"legal arguments, courtroom combat"}],"note":"03 - Astrology/Interpretations/Mercury–Mars.md"},"Mercury-Neptune":{"pair":"Mercury–Neptune","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (sextile, trine), Mercury-Neptune is \"favorable for the collective imagination; new ideas, aspirations, efforts in arts and literature,\" as the tradition describes. The national conversation turns toward idealism and creative possibility. Arts and literature flourish. Media produces work that inspires rather than deceives. Science communication reaches the public in ways that spark genuine wonder. Health messaging resonates. The collective imagination is engaged constructively — people dream together, and the dreams are at least adjacent to reality.","hostile":"Under hostile aspects (conjunction, square, opposition), Mercury-Neptune produces what the tradition vividly describes as \"remarkable frauds and manias; speculative bubbles; apocalyptic frenzies; lurid crimes seize public imagination.\" This is the misinformation aspect par excellence. Fact and fiction become indistinguishable in the public discourse. Speculative bubbles inflate as Mercury's commerce is dissolved by Neptune's fantasies. Apocalyptic narratives — whether about the economy, public health, or the end of civilization — grip the national conversation. The media amplifies rather than debunks. Lurid crimes or scandals dominate headlines not because of their importance but because Neptune makes the public unable to look away. Propaganda operates at peak effectiveness because critical thinking has been dissolved.","trigger":"Mercury-Neptune aspects are fast-moving (days to about two weeks) and mark the specific moments when propaganda, collective fantasy, misinformation, or inspired imagination activate whatever broader outer-planet storylines are in play.","current_text":null,"text":[],"arcs":[{"arc":"The Information War","note":"misinformation peaks, narrative confusion"},{"arc":"Fringe, Disclosure & Health","note":"health messaging, science communication"},{"arc":"The Great Reckoning","note":"leaks and rumor cycles, fact vs fiction"}],"note":"03 - Astrology/Interpretations/Mercury–Neptune.md"},"Mercury-Pluto":{"pair":"Mercury–Pluto","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (sextile, trine), the national conversation successfully grapples with hidden or plutocratic power. Investigative journalism produces genuine revelations. Intelligence agencies communicate effectively with civilian authorities. Financial disclosures expose corruption in ways that lead to accountability rather than just outrage. The media functions as a tool of democratic transparency — surfacing what was buried, naming what was hidden. Commerce is restructured in ways that reduce the influence of monopolistic or criminal networks.","hostile":"Under hostile aspects (conjunction, square, opposition), Mercury's information channels become instruments of plutocratic control — or are overwhelmed by what they uncover. Media is weaponized by powerful interests to destroy opponents. Intelligence leaks are used as political weapons rather than instruments of transparency. Hidden financial data surfaces in ways that destabilize markets or paralyze governance. The national conversation is hijacked by revelations so dark or complex that the public cannot process them. Investigative bombshells land but produce paralysis rather than reform. The tone is not Neptunian confusion — it is the vertiginous clarity of seeing exactly how deep the corruption goes.","trigger":"Mercury-Pluto aspects are fast-moving (days to about two weeks) and mark the specific moments when hidden information, plutocratic media control, and investigative revelations activate whatever broader outer-planet storylines are in play.","current_text":null,"text":["Because the tradition does not specifically delineate this pair, treat Mercury-Pluto readings as provisional and weight them less heavily than pairs the tradition addresses directly."],"arcs":[{"arc":"The Great Reckoning","note":"secrets exposed, investigative bombshells"},{"arc":"The Information War","note":"media as power tool, deep-state comms"},{"arc":"The Monetary Reset","note":"hidden financial data surfacing"}],"note":"03 - Astrology/Interpretations/Mercury–Pluto.md"},"Mercury-Saturn":{"pair":"Mercury–Saturn","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (conjunction, sextile, trine), Mercury-Saturn is what the tradition calls \"a very favorable aspect.\" The result is that \"transport and communications infrastructure provides lasting benefits; favors the laboring classes, higher wages.\" This is not flashy — it is the nation's communication and commerce systems being built or maintained with Saturnian durability. Infrastructure legislation passes and actually works. Trade agreements benefit workers. The media operates with discipline and seriousness rather than sensationalism. Education emphasizes rigor. The laboring classes see tangible improvements — higher wages, better working conditions — because Mercurial commerce is structured by Saturnian fairness.","hostile":"Under hostile aspects (square, opposition), Saturn's weight falls on Mercury's domains. the tradition describes \"trade and commerce hindered; transportation delayed; conditions worsen for laboring classes.\" Information is controlled, censored, or suppressed. The media faces official constraints. Transportation systems break down or suffer delays. Trade stalls. The economy's commercial arteries constrict. The laboring classes — the people who depend on functional transport and fair commerce — bear the brunt. Official communications become stiff, punitive, and designed to limit rather than inform.","trigger":"Mercury-Saturn aspects are fast-moving (days to about two weeks) and mark the specific moments when communication limits, commercial constraints, and infrastructure stress activate whatever broader outer-planet storylines are in play.","current_text":null,"text":[],"arcs":[{"arc":"The Information War","note":"censorship, controlled messaging"},{"arc":"The Great Reckoning","note":"institutional communications, legal constraints"},{"arc":"Border & Homeland","note":"policy announcements, regulatory language"}],"note":"03 - Astrology/Interpretations/Mercury–Saturn.md"},"Mercury-Uranus":{"pair":"Mercury–Uranus","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (conjunction, sextile, trine), Mercury-Uranus \"encourages reform; legislation proposed while in effect is more likely successful and popular; scientific discovery and technological innovation benefit,\" as the tradition describes. The national conversation shifts toward the future. New ideas break through media gatekeepers and reach the public. Reform legislation finds unexpected support. Technology leaps forward — not incrementally but disruptively. Whistleblowers release information that serves the public interest. The education system embraces innovation. This is the aspect of the breakthrough idea that actually lands.","hostile":"Under hostile aspects (square, opposition), the tradition warns of \"political turbulence; unexpected troubles; strange events and unsolved crimes become subjects of obsessive public interest.\" The information landscape is disrupted chaotically. Viral moments seize the national conversation but distort rather than inform. Technology fails at the worst moment — cyberattacks, system outages, infrastructure collapses. Political discourse becomes erratic and unpredictable. The public fixates on bizarre crimes or strange events that resist explanation, consuming media bandwidth that could go to substantive issues. Leaks happen, but they create confusion rather than clarity.","trigger":"Mercury-Uranus aspects are fast-moving (days to about two weeks) and mark the specific moments when information breakthroughs, technological disruption, and unexpected revelations activate whatever broader outer-planet storylines are in play.","current_text":null,"text":[],"arcs":[{"arc":"The Information War","note":"information breakthroughs, viral moments"},{"arc":"The Monetary Reset","note":"market-moving leaks, tech announcements"},{"arc":"Fringe, Disclosure & Health","note":"disclosure drops, whistleblower communications"}],"note":"03 - Astrology/Interpretations/Mercury–Uranus.md"},"Mercury-Venus":{"pair":"Mercury–Venus","cycle":"fast (weeks to months)","current":"","prev":"","helpful":"Under helpful aspects (conjunction, sextile, trine), Mercury-Venus is \"mildly favorable for national peace, contentment; beneficial for prosperity, decreased unemployment; favorable for women's issues,\" as the tradition describes. Trade negotiations proceed smoothly. Economic messaging from the government is well-received. The media covers culture, the arts, and human interest stories rather than conflict. Unemployment ticks down. Consumer sentiment improves. Women's issues gain favorable media attention. Diplomatic communications are warm and productive. This is a gentle, pleasant influence — nothing dramatic, but the nation feels a little more at ease.","hostile":"Under hostile aspects (square, opposition), the effect is \"mildly unfavorable; existing grievances remain; warns of troubled economic conditions.\" Trade talks stall or produce unsatisfying results. Economic messaging falls flat — the public is not reassured. Media coverage turns sour on cultural or social topics. Unemployment holds steady or worsens slightly. Existing economic grievances are not resolved and may be amplified by media attention. The mildness of this hostile aspect is notable — Mercury-Venus friction rarely produces crises, but it does produce a nagging sense that the economy is not working for people and the national conversation is not addressing it.","trigger":"Mercury-Venus aspects are fast-moving (days to about a week) and mark brief windows when trade sentiment, cultural communication, and economic mood activate whatever broader outer-planet storylines are in play.","current_text":null,"text":[],"arcs":[{"arc":"The Information War","note":"diplomatic language, media charm"},{"arc":"The Monetary Reset","note":"trade talks, market sentiment shifts"}],"note":"03 - Astrology/Interpretations/Mercury–Venus.md"},"Neptune-Pluto":{"pair":"Neptune–Pluto","cycle":"~492 years","current":"Long sextile (in effect ~1941–2035)","prev":"1891-92 in Gemini","helpful":null,"hostile":null,"trigger":null,"current_text":"This sextile has been in effect since the early 1940s and persists until roughly 2035. The ENTIRE modern era — WWII and the creation of the post-war international order, the Cold War contest between the superpowers, the digital revolution that restructured every nation's economy and military — unfolds within this single harmonious phase. It is the background hum beneath all the shorter cycles. Every government, every corporation, every popular movement in the Freedom 250 chronicle operates within this window of opportunity: the chance for the nations to put deep civilizational ideals into constructive, practical expression before the sextile fades.","text":["The deepest, slowest cycle in mundane astrology — half a millennium per revolution. This is not the rise and fall of governments or even of national orders; this is the rise and fall of entire civilizations and the collective ideals that animate them. When the dissolving tide of mass consciousness (Neptune) meets the civilizational purge-force (Pluto), the foundational myths of an age are born or die. The 1891-92 conjunction in Gemini seeded the current movement toward global culture, mass communication, and the information age — the very infrastructure through which nations now wage their wars, conduct their economies, and govern their peoples.","the tradition does not give a specific Neptune-Pluto entry (Pluto skepticism applies doubly at this timescale). The civilizational-scale framing from the old cycle-school and Baigent remains the best lens: this cycle operates beneath and behind all the shorter cycles, shaping the assumptions that governments, corporations, and the laboring classes take for granted. The helpful expression means the deep civilizational ideals and the transformative mass forces cooperate; the hostile expression means entire paradigms of governance and economic life collapse and must be rebuilt from scratch over centuries."],"arcs":[{"arc":"Border & Homeland","note":"the sovereignty-first ideal in action"},{"arc":"War Footing — Iran","note":"the Middle East powder keg and military posture"},{"arc":"Fringe, Disclosure & Health","note":"health freedom, disclosure, and institutional trust in science"},{"arc":"Great-Power Realignment","note":"the multipolar world taking shape"}],"note":"03 - Astrology/Interpretations/Neptune–Pluto.md"},"Saturn-Neptune":{"pair":"Saturn–Neptune","cycle":"~36 years","current":"Conjunction in Aries (exact 02/20/2026)","prev":"1989 in Capricorn (Fall of Berlin Wall)","helpful":null,"hostile":null,"trigger":null,"current_text":"The post-1989 liberal-globalist establishment — the bureaucracy, the intelligence agencies, the multilateral institutions — is the \"negatively crystallized\" structure being dissolved. The executive branch and the populist movement are the agents of dissolution; the civil service, the courts, and the legacy press are the structures resisting it. The new collective image is forged in Aries — primal, sovereignty-first, built around national self-interest rather than global consensus. The Aries Point (0°) = where the personal and the political become indistinguishable; the government and the people face the same survival question simultaneously.","text":["the old cycle-school's paramount cycle of national life. Every 36 years, the bureaucratic establishment (Saturn) meets the dissolving tide of collective idealism (Neptune): whatever has become negatively crystallized in the nation's institutions is broken down, and a new collective image descends to replace it. The conjunction is the seed of that image — raw, unformed, full of potential and delusion in equal measure. Previous conjunctions: 1989 (Capricorn) = the Soviet state apparatus dissolves, the Cold War establishment collapses; 1953 (Libra) = the Cold War order crystallizes between the superpowers; 1917 (Leo) = the Russian monarchy falls, the laboring classes seize state power; 1882 (Taurus) = organized labor rises as a political force against the industrial establishment.","Hostile Saturn-Neptune aspects bring \"disorganization, confusion, and delay; some serious loss affects the nation, authority figures face discredit or downfall\" — the establishment loses its grip and the people lose confidence in their leaders. Helpful Saturn-Neptune aspects bring \"new laws and reforms that benefit the people; the popular interest gains strength; the national economy improves through stability.\" The conjunction partakes of both: the old order's authority figures are discredited (hostile), but the seed of beneficial reform for the laboring classes and the general public is planted (helpful)."],"arcs":[{"arc":"The Great Reckoning","note":"the old institutional order dissolving"},{"arc":"The Information War","note":"the battle over which new collective image replaces the old one"},{"arc":"The Monetary Reset","note":"the old financial architecture giving way"},{"arc":"Border & Homeland","note":"the sovereignty-first ideal in Aries"},{"arc":"War Footing — Iran","note":"the Middle East powder keg and military posture"},{"arc":"Fringe, Disclosure & Health","note":"health freedom, disclosure, and institutional trust in science"},{"arc":"Great-Power Realignment","note":"the multipolar world taking shape"}],"note":"03 - Astrology/Interpretations/Saturn–Neptune.md"},"Saturn-Pluto":{"pair":"Saturn–Pluto","cycle":"~33 years","current":"Sextile (exact 07/2025, 03/2026)","prev":"January 2020 in Capricorn (COVID)","helpful":null,"hostile":null,"trigger":null,"current_text":"The first cooperative flowering after the 2020 purge. The executive branch, the civil service, and the corporate sector are finding productive expression for whatever was stripped down during COVID — the new public health regime, the restructured supply chains, the reorganized federal workforce. The sextile = the government benefits from efficient, constructive effort; the establishment begins to rebuild on firmer foundations.","text":["The cycle of institutional death and resurrection in national life. When the establishment (Saturn) meets the underworld purge (Pluto), entire state structures are stripped to their bones and rebuilt. the old cycle-school: emerging nations, deep cultural transformations, \"resurrections.\" The square = crisis of authority in the government, public discontent with the existing order. India and Pakistan won independence from the British establishment days after the 1947 conjunction. The January 2020 conjunction in Capricorn = COVID, the executive branch assuming emergency powers, the civil service and public health bureaucracy exposed, the national economy stripped to its bones.","the tradition does not give a specific Saturn-Pluto entry (Pluto skepticism), but his Mars-Saturn delineation provides the closest parallel for the hostile expression: \"public discontent with the existing order,\" rioting, crimes against authority, the government losing the support of the people. The helpful expression — the sextile and trine — brings efficiency, constructive effort, and benefit to the executive power; the bureaucracy and the laboring classes find common purpose in rebuilding what was purged."],"arcs":[{"arc":"The Great Reckoning","note":"purging the body politic"},{"arc":"The Information War","note":"the battle over which new collective image replaces the old one"},{"arc":"The Monetary Reset","note":"the old financial architecture giving way"},{"arc":"Border & Homeland","note":"the sovereignty-first ideal in action"},{"arc":"War Footing — Iran","note":"Saturn-Pluto has strong Israel correlation alongside Saturn-Uranus"},{"arc":"Great-Power Realignment","note":"emerging/re-emerging nations"}],"note":"03 - Astrology/Interpretations/Saturn–Pluto.md"},"Saturn-Uranus":{"pair":"Saturn–Uranus","cycle":"~45 years","current":"Sextile (exact 08/2025, 01/2026)","prev":"1988 in Sagittarius","helpful":null,"hostile":null,"trigger":null,"current_text":"After the brutal square of 2021 — which correlated with the institutional establishment battling the populist movement, vaccine mandates vs. bodily autonomy, the executive branch vs. state governors — the sextile brings the two forces into cooperative expression. The party in power benefits from orderly change; the bureaucracy and the reform movement find common ground. The government can modernize the civil service, restructure federal agencies, and advance technological legislation without triggering the \"epic struggles\" of the square.","text":["the old cycle-school: conservative/authoritarian energy, the \"politics of Order,\" imperialism, heavy capital concentration. The fundamental tension between the establishment (Saturn) and the democratic-revolutionary impulse (Uranus). Strong Middle East signature — Israel was conceived under a Saturn-Uranus conjunction, Egypt's republics formed at key phases. When these two meet, the government confronts the people's demand for change head-on.","the tradition's delineation is vivid. Helpful Saturn-Uranus aspects bring \"constructive reform and orderly change; supports the party in power\" — the executive branch and the legislature cooperate to modernize the nation's institutions without upheaval. Hostile Saturn-Uranus aspects bring \"epic struggles; very unfortunate for the government, piling up troubles with no quick solution\" — the establishment digs in, the populist and reform movements attack, and the resulting deadlock damages the national economy and public morale alike."],"arcs":[{"arc":"The Great Reckoning","note":"the establishment"},{"arc":"The Information War","note":"the battle over which new collective image replaces the old one"},{"arc":"The Monetary Reset","note":"the old financial architecture giving way"},{"arc":"Border & Homeland","note":"order vs. liberation in domestic policy"},{"arc":"War Footing — Iran","note":"the Middle East connection Baigent documented"},{"arc":"Fringe, Disclosure & Health","note":"health freedom, disclosure, and institutional trust in science"},{"arc":"Great-Power Realignment","note":"the multipolar world taking shape"}],"note":"03 - Astrology/Interpretations/Saturn–Uranus.md"},"Sun-Jupiter":{"pair":"Sun–Jupiter","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (conjunction, sextile, trine), Sun-Jupiter is what the tradition calls \"THE most favorable aspect in mundane astrology.\" The result is \"peace and prosperity at home and abroad; the government receives significant good luck.\" Everything breaks the executive's way. The economy expands, foreign relations warm, legislation passes, and the judiciary cooperates with (or at least does not obstruct) the government's agenda. The President looks magnanimous and successful. Diplomatic summits produce real agreements. The national mood is confident and generous. This is the closest a mundane chart gets to an unambiguous blessing.","hostile":"Under hostile aspects (square, opposition), Jupiter's excess shows its shadow side. Prosperity may still come, but it arrives alongside \"lurid scandals and highly publicized crimes,\" as the tradition notes. The government overreaches — too much spending, too much confidence, too many promises. The judiciary pushes back against executive overreach. Foreign relations are marked by arrogance rather than diplomacy. The economy runs hot but unevenly, generating resentment. The scandals that emerge under hostile Sun-Jupiter tend to be spectacular, theatrical, and impossible to ignore — Jupiter does nothing quietly.","trigger":"Sun-Jupiter aspects are fast-moving (days to about two weeks) and mark the specific moments when prosperity, judicial action, diplomatic developments, and national confidence activate whatever broader outer-planet storylines are in play.","current_text":null,"text":[],"arcs":[{"arc":"The Great Reckoning","note":"leadership confidence, executive authority"},{"arc":"The Monetary Reset","note":"economic confidence, trade announcements"},{"arc":"Great-Power Realignment","note":"diplomatic expansion, summit moments"}],"note":"03 - Astrology/Interpretations/Sun–Jupiter.md"},"Sun-Mars":{"pair":"Sun–Mars","cycle":"fast (weeks to months)","current":"","prev":"","helpful":null,"hostile":"Under hostile aspects (square, opposition), the picture inverts sharply. the tradition warns of \"conflict and disagreement; heated public passions; partisan hatreds accentuated; violence against government officials possible.\" The executive picks fights or is targeted by them. Political rhetoric turns martial. Industrial disputes flare, crime rates spike, and the risk of actual violence — against officials or between political factions — rises. Military adventures undertaken during these aspects tend to go badly or provoke fierce domestic opposition.","trigger":"Sun-Mars aspects are fast-moving (days to a couple of weeks) and act as ignition points, lighting up the slower outer-planet themes wherever Mars's combative energy meets executive power.","current_text":null,"text":["When the Sun and Mars form helpful aspects (conjunction, sextile, trine), the result is a strengthened executive acting decisively and effectively. the tradition describes \"improvements in public health and the nation's position relative to foreign powers; strength and success to the government, especially fortunate in military affairs.\" The President looks commanding; military operations go well; the nation projects force credibly. Public health initiatives gain traction because Mars-as-surgeon works cooperatively with executive authority."],"arcs":[{"arc":"War Footing — Iran","note":"military decisions, executive force"},{"arc":"Border & Homeland","note":"enforcement actions, deportation operations"},{"arc":"The Great Reckoning","note":"legal offensives, aggressive prosecution"}],"note":"03 - Astrology/Interpretations/Sun–Mars.md"},"Sun-Mercury":{"pair":"Sun–Mercury","cycle":"fast (weeks to months)","current":"","prev":"","helpful":null,"hostile":null,"trigger":"The Sun-Mercury conjunction is fast-moving (exact for roughly a day, with an orb of influence lasting about a week) and marks specific moments when executive communication activates whatever broader storylines are in play.","current_text":null,"text":["Sun and Mercury are never far apart, so their only major aspect is the conjunction. the tradition describes this as \"favorable for intellectual and scientific activities; important speeches and successful public relations by the head of government.\" When the Sun and Mercury meet, the President speaks and the nation listens. Major policy addresses, State of the Union moments, press conferences that actually land — these cluster around Sun-Mercury conjunctions. The executive branch's message gets through clearly.","This is the government's best window for public communication. Scientific announcements carry weight, education policy gains traction, and the media amplifies rather than distorts the executive's message. Trade negotiations benefit from clear terms. Because Mercury also rules transport, infrastructure announcements or ribbon-cuttings under this conjunction tend to be well-received and effective.","The absence of hostile aspects between these two planets means Sun-Mercury is almost always a mildly favorable influence. The main risk is overconfidence in messaging — the government may assume its words landed when the audience was already tuned out."],"arcs":[{"arc":"The Information War","note":"official announcements, policy messaging"},{"arc":"The Monetary Reset","note":"economic data releases, Fed communications"},{"arc":"The Great Reckoning","note":"legal filings, court rulings"}],"note":"03 - Astrology/Interpretations/Sun–Mercury.md"},"Sun-Neptune":{"pair":"Sun–Neptune","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (sextile, trine), the government rides a wave of popular enthusiasm. \"government is popular with the masses; success through popular enthusiasm or sheer luck.\" The President appears charismatic, even inspired. Popular movements align with executive goals rather than opposing them. Propaganda works — but in the helpful version, it works because the message resonates with genuine collective feeling. The nation experiences a sense of unity. Luck plays an outsized role; things simply go the government's way for reasons no one can fully explain.","hostile":"Under hostile aspects (conjunction, square, opposition), Sun-Neptune becomes what the tradition calls \"FAR AND AWAY the most unfortunate indication\" in mundane astrology — \"something in the nature of a downfall or collapse.\" The executive is engulfed by confusion, disorder, and the failure of legislation. Propaganda backfires or is exposed. The government becomes deeply unpopular, and those in power suffer \"unpopularity and misfortune.\" Mass movements turn against the state. Scandals erupt that dissolve public trust. The President appears lost, deluded, or actively deceptive. This is not a sharp Uranian crisis — it is a slow drowning, where the ground gives way beneath the government's feet and nothing solid can be found to stand on.","trigger":"Sun-Neptune aspects are fast-moving (days to about two weeks) and mark the specific moments when mass sentiment, propaganda, confusion, or collective vision activate whatever broader outer-planet storylines are in play.","current_text":null,"text":["The asymmetry here is extreme. Helpful Sun-Neptune is pleasant but vague; hostile Sun-Neptune is one of the most destructive combinations in the mundane astrologer's toolkit."],"arcs":[{"arc":"The Great Reckoning","note":"institutional confusion, scandal revelations"},{"arc":"The Information War","note":"propaganda peaks, narrative confusion"},{"arc":"Fringe, Disclosure & Health","note":"health scares, disclosure moments"}],"note":"03 - Astrology/Interpretations/Sun–Neptune.md"},"Sun-Pluto":{"pair":"Sun–Pluto","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (sextile, trine), the executive branch successfully confronts or harnesses transformative and plutocratic forces. The President gains power by exposing corruption, reforming intelligence agencies, or channeling the nation's deep structural energies constructively. Investigations into organized crime or financial fraud produce results. Nuclear diplomacy advances. The government appears to have command over forces that normally operate in the shadows — a rare and potent position.","hostile":"Under hostile aspects (conjunction, square, opposition), the executive is drawn into a power struggle with forces that operate beneath the surface of ordinary politics — plutocratic elites, intelligence agencies, or organized criminal networks. Corruption scandals erupt that implicate the highest levels of government. The President appears either complicit in hidden power structures or overwhelmed by them. Nuclear confrontations or existential policy crises force the government into zero-sum thinking. The tone is not Neptunian confusion but Plutonian exposure — the ugly machinery beneath the state becomes visible, and the public is forced to reckon with it.","trigger":"Sun-Pluto aspects are fast-moving (days to about two weeks) and mark the specific moments when plutocratic power, hidden forces, and transformative crises activate whatever broader outer-planet storylines are in play.","current_text":null,"text":["Because the tradition does not specifically delineate this pair, treat Sun-Pluto readings as provisional and weight them less heavily than pairs the tradition addresses directly."],"arcs":[{"arc":"The Great Reckoning","note":"power exposed, corruption surfacing"},{"arc":"The Monetary Reset","note":"financial power plays, deep-state economics"},{"arc":"War Footing — Iran","note":"existential confrontation, nuclear moments"}],"note":"03 - Astrology/Interpretations/Sun–Pluto.md"},"Sun-Saturn":{"pair":"Sun–Saturn","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (sextile, trine), Sun-Saturn \"gives the government strength rather than popularity,\" as the tradition puts it. The executive gains the ability to \"hold or extend power by skillful maneuvering.\" This is not a beloved government — it is a competent one. Legislation passes not because the public is enthusiastic but because the administration works the levers of institutional power effectively. Bureaucratic machinery runs smoothly. The nation's infrastructure holds. The President looks serious, disciplined, and in command of the structural realities of governance.","hostile":"Under hostile aspects (conjunction, square, opposition), Saturn's weight falls on the executive. the tradition describes \"loss of power and popularity; obstacles and delays; economy stagnates.\" The government looks old, tired, or out of touch. Legislative agendas stall. The economy contracts or flatlines — Saturn squeezes rather than stimulates. The President ages visibly under the burden. The conservative opposition gains ground, the laboring classes feel the pinch, and the public mood turns grim and patient (Saturn's patience is not optimistic — it is the patience of people who have stopped expecting things to improve).","trigger":"Sun-Saturn aspects are fast-moving (days to about two weeks) and mark specific moments when structural limits, institutional power, and the weight of the established order activate whatever broader outer-planet storylines are in play.","current_text":null,"text":[],"arcs":[{"arc":"The Great Reckoning","note":"institutional limits exposed, leadership tested"},{"arc":"Border & Homeland","note":"sovereignty enforcement, structural border policy"},{"arc":"Great-Power Realignment","note":"alliance obligations, structural diplomacy"}],"note":"03 - Astrology/Interpretations/Sun–Saturn.md"},"Sun-Uranus":{"pair":"Sun–Uranus","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (sextile, trine), Sun-Uranus brings \"successful reforms and changes for the better; new ideas enter public conversation,\" as the tradition describes. The government innovates. Reforms that would normally face institutional resistance pass smoothly. The President appears forward-thinking, even visionary. Technology policy advances. The public appetite for change is met with constructive legislative action rather than chaos. Alliances are restructured in ways that benefit the nation.","hostile":"Under hostile aspects (conjunction, square, opposition), Uranus strikes the executive like lightning. the tradition warns of \"sudden unexpected troubles for government; bad decisions; abuses of power; alliances break down.\" The government is blindsided — by a crisis, a scandal, a technological disruption, or a popular revolt it did not see coming. Executive decisions made under these aspects tend to be impulsive and poorly considered. Abuses of power become visible and generate backlash. International alliances fracture without warning. The nation lurches rather than pivots, and the disruption tends to leave lasting instability.","trigger":"Sun-Uranus aspects are fast-moving (days to about two weeks) and mark the specific moments when sudden disruption, reform impulses, and unexpected events activate whatever broader outer-planet storylines are in play.","current_text":null,"text":[],"arcs":[{"arc":"The Information War","note":"sudden disruptions to media landscape"},{"arc":"The Monetary Reset","note":"market shocks, flash crashes"},{"arc":"Great-Power Realignment","note":"diplomatic surprises, sudden alliance shifts"}],"note":"03 - Astrology/Interpretations/Sun–Uranus.md"},"Sun-Venus":{"pair":"Sun–Venus","cycle":"fast (weeks to months)","current":"","prev":"","helpful":null,"hostile":null,"trigger":"Sun-Venus conjunctions are fast-moving (days to about a week of orb) and mark brief windows when soft power, economic sentiment, and diplomatic goodwill activate whatever broader planetary themes are in play.","current_text":null,"text":["Like Sun-Mercury, Sun-Venus stays close, so the conjunction is the primary aspect. the tradition describes it as favorable for \"national prosperity; tourism, entertainment, consumer expenditures driving growth; friendly foreign relations; favorable for women's issues.\" This is the soft-power conjunction — the nation looks attractive, diplomacy runs on charm rather than threats, and the economy benefits from people spending money on things that make them happy. Trade agreements reached under this influence tend to be mutually beneficial. The entertainment and tourism industries do well.","The only hostile aspect possible between Sun and Venus is the semisquare (45 degrees), which the tradition treats as minor. Even at its worst, Sun-Venus friction is mild — a diplomatic faux pas, a consumer confidence dip, a cultural moment that lands awkwardly rather than gracefully. There is no Sun-Venus square or opposition to worry about.","This makes Sun-Venus one of the most reliably positive triggers in mundane work. When it activates, it brings a window of goodwill, economic buoyancy, and successful diplomacy. Women's issues and social welfare legislation get favorable attention. The President benefits from personal likability rather than fear or respect."],"arcs":[{"arc":"Great-Power Realignment","note":"diplomatic charm, soft-power moments"},{"arc":"The Monetary Reset","note":"trade agreements, market sentiment"},{"arc":"The Information War","note":"cultural messaging, media aesthetics"}],"note":"03 - Astrology/Interpretations/Sun–Venus.md"},"Uranus-Neptune":{"pair":"Uranus–Neptune","cycle":"~172 years","current":"Sextile from Gemini/Aries (exact 08/2025)","prev":"1993 in Capricorn","helpful":null,"hostile":null,"trigger":null,"current_text":"The first cooperative flowering of whatever was seeded in 1993. The democratic-technological lightning bolt (Uranus in Gemini = the information sector, AI, the national conversation) cooperates with the new collective ideal (Neptune in Aries = sovereignty-first, primal national self-interest). The political class and the people find alignment; the legislature can pass constructive reform; the national economy benefits from the technology sector's expansion meeting the popular demand for national renewal. The sextile = active, willing cooperation between the individual and the mass, between the corporations building the future and the people demanding it serve their interests.","text":["the old cycle-school: the interaction between capital and labour, conservatism and liberalism, the individual and the mass — the fundamental polarity of national economic life. the tradition's binary-pair framework places Uranus and Neptune as the outermost pair: the democratic-individual impulse vs. the collective-unity impulse. The 1993 Capricorn conjunction seeded the post-Cold War order — globalization, the internet economy, the \"end of history\" narrative in which the Western establishment declared permanent victory over the laboring classes' alternative.","the tradition's delineation for this pair is among his \"most fortunate\" when helpful: \"harmony between the political class and the people, constructive reform\" — the legislature and the executive branch cooperate with the popular will, the national economy benefits, democratic causes advance. Hostile Uranus-Neptune aspects bring \"turmoil, disruption, confusion; the government is shaken; attempted reforms bog down\" — the political class loses touch with the masses, the bureaucracy's reform efforts fail, and the people lose confidence in democratic institutions."],"arcs":[{"arc":"The Great Reckoning","note":"the old institutional order dissolving"},{"arc":"The Information War","note":"the internet (born at the 1993 conjunction) now the battlefield"},{"arc":"The Monetary Reset","note":"the economic order born in 1993 being restructured"},{"arc":"Border & Homeland","note":"the sovereignty-first ideal in action"},{"arc":"War Footing — Iran","note":"the Middle East powder keg and military posture"},{"arc":"Fringe, Disclosure & Health","note":"health freedom, disclosure, and institutional trust in science"},{"arc":"Great-Power Realignment","note":"capital vs labour on a global stage"}],"note":"03 - Astrology/Interpretations/Uranus–Neptune.md"},"Uranus-Pluto":{"pair":"Uranus–Pluto","cycle":"~127 years","current":"Trine from Gemini/Aquarius (exact 09/2025, 07/2026)","prev":"1965-66 in Virgo (counterculture, computers)","helpful":null,"hostile":null,"trigger":null,"current_text":"The harvest phase of the 1960s revolution, flowing freely. The democratic-technological fire (Uranus in Gemini = the information sector, AI, the press) pours into the civilizational transformation (Pluto in Aquarius = the paradigm shift in how the people organize politically). The corporations building AI, the legislature writing technology law, the executive branch restructuring federal data systems — all are riding this trine. The radical restructuring of how the nation thinks and communicates arrives without the violence of a conjunction, benefiting the party in power and the technology sector alike.","text":["The most explosive combination in mundane astrology. the old cycle-school: radical restructuring of civilizations — \"building on the ruins of the old.\" Not reform but revolution. When the democratic-technological impulse (Uranus) meets the mass-transformative underworld force (Pluto), entire national orders are overturned and rebuilt. The 1965-66 conjunction seeded the computer age, the counterculture, the civil rights revolution, and the generation now holding executive power across the Western nations. Technology and mass upheaval arrive together; the laboring classes and the countercultures gain tools that the establishment cannot control.","the tradition does not give a specific Uranus-Pluto entry (Pluto skepticism), but his Uranus chapter clarifies the mundane stakes: Uranus represents \"democracy, the individual, countercultures, machines/computers/internet.\" The helpful expression channels revolutionary energy into technological breakthroughs that benefit the people and restructure the national economy without violence. The hostile expression unleashes mass upheaval against the government — failed states, revolutionary movements, the destruction of the existing corporate and bureaucratic order."],"arcs":[{"arc":"The Great Reckoning","note":"the old institutional order dissolving"},{"arc":"The Information War","note":"Technology/AI, the Promethean awakening of information itself"},{"arc":"The Monetary Reset","note":"Crypto as Promethean disruption of Plutocratic financial power"},{"arc":"Border & Homeland","note":"the sovereignty-first ideal in action"},{"arc":"War Footing — Iran","note":"the Middle East powder keg and military posture"},{"arc":"Fringe, Disclosure & Health","note":"Disclosure, the hidden made visible"},{"arc":"Great-Power Realignment","note":"the multipolar world taking shape"}],"note":"03 - Astrology/Interpretations/Uranus–Pluto.md"},"Venus-Jupiter":{"pair":"Venus–Jupiter","cycle":"fast (weeks to months)","current":"","prev":"","helpful":null,"hostile":"Under hostile aspects (square, opposition), Jupiter's expansive nature turns Venus's love of ease into \"excessive government expenditures; public and private extravagance; taxes become a greater burden; fraud, scandal, excessive luxury\" (the tradition). The corporate sector over-leverages. Charitable organizations are exposed for waste or self-dealing. Government spending on social programs balloons without discipline. The scandals that erupt under hostile Venus-Jupiter tend to involve luxury, fraud, and the misuse of public funds — the nation discovers that its generosity has been exploited.","trigger":"Venus-Jupiter aspects are fast-moving (days to a couple of weeks) and mark the specific moments when economic optimism, diplomatic goodwill, or their shadows — extravagance and fraud — activate the broader outer-planet storylines.","current_text":null,"text":["the tradition calls this \"one of the best aspects in any mundane chart,\" and it is easy to see why. Under helpful aspects (conjunction, sextile, trine), Venus-Jupiter brings \"peace and goodwill domestically and abroad; prosperity and settlement of quarrels; particularly beneficial for women's interests and Venus-ruled economic sectors.\" The courts settle disputes rather than inflame them. Charitable organizations flourish. Diplomacy works. The arts, entertainment, tourism, and luxury sectors expand. Women's issues advance — legislation, representation, economic participation all benefit. It is the mundane astrologer's favorite transit for a reason."],"arcs":[{"arc":"The Monetary Reset","note":"economic optimism, trade expansion"},{"arc":"Great-Power Realignment","note":"diplomatic generosity, alliance-building"},{"arc":"Fringe, Disclosure & Health","note":"wellness culture, health spending"}],"note":"03 - Astrology/Interpretations/Venus–Jupiter.md"},"Venus-Mars":{"pair":"Venus–Mars","cycle":"fast (weeks to months)","current":"","prev":"","helpful":null,"hostile":"Under hostile aspects (square, opposition, poorly-placed conjunction), Venus-Mars brings what the tradition calls conditions \"unfortunate for economic conditions; excessive government expenditure; scandals; birthrate declines.\" The economy suffers because martial energy disrupts commercial harmony. Government spending surges — often on military or enforcement — at the expense of the arts, diplomacy, and social programs. Scandals erupt, frequently involving the intersection of sex and power. The birthrate decline signals a nation where the masculine and feminine principles are at war rather than in partnership.","trigger":"Venus-Mars aspects are fast-moving (days to a couple of weeks) and act as ignition points, lighting up the slower outer-planet themes wherever trade-versus-conflict or diplomacy-versus-force tensions are already simmering.","current_text":null,"text":["Venus-Mars is the oldest polarity in mundane work: diplomacy versus conflict, trade versus war, the drawing room versus the battlefield. Under helpful aspects (conjunction when well-placed, sextile, trine), the tradition describes results \"favorable for economic matters; improvement of domestic and foreign trade; increase in birthrate; fortunate for entertainment.\" The economy benefits because Mars's energy is channeled into productive enterprise rather than destruction. Entertainment and the arts flourish — the nation is in a mood to enjoy itself. The birthrate note is distinctive: when the masculine and feminine principles cooperate, the nation literally grows."],"arcs":[{"arc":"Great-Power Realignment","note":"diplomacy vs conflict, negotiation and assertion"},{"arc":"The Monetary Reset","note":"trade wars, economic competition"},{"arc":"War Footing — Iran","note":"peace talks amid military posture"}],"note":"03 - Astrology/Interpretations/Venus–Mars.md"},"Venus-Neptune":{"pair":"Venus–Neptune","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (conjunction when well-placed, sextile, trine), Venus-Neptune \"promotes peace, contentment, general goodwill; lessens class conflict; benefits laboring classes; charitable projects flourish\" (the tradition). This is one of the few conditions where Neptune's dissolving power works constructively — the walls between social classes soften, charitable impulses translate into real action, and the nation experiences a genuine moment of collective goodwill. The arts reach their highest expression. Diplomatic idealism produces actual agreements. The laboring classes benefit because the collective mood favors generosity over competition.","hostile":"Under hostile aspects (square, opposition), the combination becomes what the tradition calls \"unfortunate for every aspect of social life; encouraging class conflict and hatred; warns of scandals, fraud, embezzlement.\" Value becomes illusion — financial bubbles inflate, currencies lose coherent meaning, Ponzi schemes proliferate. Class conflict intensifies as Neptune's mob energy targets Venus's domains of wealth and beauty. Scandals involving fraud and embezzlement dominate the news, especially in the arts, entertainment, or charitable sectors. Diplomatic agreements turn out to be illusory. The laboring classes are deceived by false promises.","trigger":"Venus-Neptune aspects are fast-moving (days to a couple of weeks) and mark the specific moments when financial bubbles, charitable impulses, or their dark twins — fraud, scandal, and class resentment — activate the broader outer-planet storylines.","current_text":null,"text":[],"arcs":[{"arc":"The Monetary Reset","note":"financial bubbles, currency confusion"},{"arc":"Great-Power Realignment","note":"diplomatic idealism, illusory agreements"},{"arc":"Fringe, Disclosure & Health","note":"wellness trends, health idealism"}],"note":"03 - Astrology/Interpretations/Venus–Neptune.md"},"Venus-Pluto":{"pair":"Venus–Pluto","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":null,"hostile":"Under hostile aspects, financial power plays dominate. Plutocratic forces — billionaire influence, corporate monopoly, hidden wealth — squeeze the economy and especially Venus-ruled sectors. Women's issues become battlegrounds for power rather than sites of genuine progress. Economic coercion (sanctions, weaponized finance, leveraged buyouts) replaces diplomacy. Hidden wealth is exposed, often through scandal, and the exposure itself becomes a tool of power. The Pluto caveat applies throughout: these delineations are less tested than the traditional planets and should be weighted accordingly.","trigger":"Venus-Pluto aspects are fast-moving (days to a couple of weeks) and mark the specific moments when financial power plays, economic transformation, or plutocratic pressure activate the broader outer-planet storylines.","current_text":null,"text":["Venus-Pluto brings women's issues and the economy face-to-face with transformative and plutocratic forces. the tradition offers no specific delineation for this pair — Pluto was not part of his framework — but the mundane logic is clear from the old cycle-school and from observed correlations. Under helpful aspects, the economy undergoes constructive transformation: hidden wealth is redirected toward productive use, financial power structures reform, and women's issues advance through encounters with deep institutional power. The arts engage with themes of death, regeneration, and the underworld — and the culture is richer for it."],"arcs":[{"arc":"The Monetary Reset","note":"financial power plays, hidden wealth exposed"},{"arc":"The Great Reckoning","note":"corruption in finance, economic accountability"},{"arc":"Great-Power Realignment","note":"economic coercion, sanctions as weapon"}],"note":"03 - Astrology/Interpretations/Venus–Pluto.md"},"Venus-Saturn":{"pair":"Venus–Saturn","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (conjunction when well-placed, sextile, trine), Venus-Saturn delivers what the tradition describes as \"good economic news; improvements in prosperity; increases in stock prices; modest but steady and enduring gains.\" This is not Jupiter's boom — it is the kind of prosperity built on discipline. The stock market rises on fundamentals rather than speculation. The establishment supports the arts and culture. Women's issues advance through institutional channels — legislation, bureaucratic reform — rather than revolution. Diplomatic alliances strengthen through obligation honored rather than generosity offered. The gains are modest but they last.","hostile":"Under hostile aspects (square, opposition), Saturn's weight crushes Venus's domains. the tradition's delineation is blunt: \"very bad news; hard times for industry and economy; losses in stock markets; trouble in banking; poverty becomes more widespread; women's issues suffer.\" The establishment's austerity falls hardest on Venus-ruled sectors — the arts lose funding, entertainment contracts, tourism collapses. Banking crises emerge. Stock markets decline. Women bear a disproportionate share of the economic pain. Diplomatic relationships freeze under the weight of unmet obligations. The bureaucracy becomes actively hostile to the pursuit of pleasure and ease.","trigger":"Venus-Saturn aspects are fast-moving (days to a couple of weeks) and mark the specific moments when financial austerity, institutional constraint, or their constructive flip side — steady, durable gains — activate the broader outer-planet storylines.","current_text":null,"text":[],"arcs":[{"arc":"The Monetary Reset","note":"financial austerity, economic limits"},{"arc":"Great-Power Realignment","note":"strained alliances, obligatory diplomacy"},{"arc":"Border & Homeland","note":"immigration economics, welfare costs"}],"note":"03 - Astrology/Interpretations/Venus–Saturn.md"},"Venus-Uranus":{"pair":"Venus–Uranus","cycle":"~1 year (Sun) / ~2 years (Mars) / ~1 year (Venus/Mercury)","current":"","prev":"","helpful":"Under helpful aspects (conjunction when well-placed, sextile, trine), Venus-Uranus is what the tradition describes as \"fortunate for prosperity and progress; beneficial changes in laws; especially favorable for women's issues.\" The economy benefits from technological disruption — new industries emerge, markets modernize. Laws change in ways that benefit women and expand social freedoms. The arts embrace innovation. Diplomatic alliances shift in constructive directions. Democracy and the counterculture find common cause with mainstream values.","hostile":"Under hostile aspects (square, opposition), Uranus's disruptive force destabilizes Venus's domains. the tradition warns this combination is \"unfortunate for the economy; widespread dissatisfaction; family, community, and social troubles.\" Markets are disrupted suddenly — currency shocks, flash crashes, technology-driven dislocations. Alliances break without warning. Social harmony fractures as radical movements clash with traditional values. Family and community structures strain under the pressure of rapid change. Women's issues become flashpoints for cultural conflict rather than sites of progress.","trigger":"Venus-Uranus aspects are fast-moving (days to a couple of weeks) and mark the specific moments when market disruptions, sudden alliance shifts, or technology-driven economic change activate the broader outer-planet storylines.","current_text":null,"text":[],"arcs":[{"arc":"The Monetary Reset","note":"market disruptions, currency shocks"},{"arc":"Great-Power Realignment","note":"sudden alliance shifts, diplomatic surprises"},{"arc":"The Information War","note":"cultural revolution, values disrupted"}],"note":"03 - Astrology/Interpretations/Venus–Uranus.md"}},"midpoints":{"SU/MO":"Vitality fused with feeling; life's central focus","SU/ME":"Confident, authoritative thinking and speech","SU/VE":"Appreciation, charm, love of beauty","SU/MA":"Energy regulation; drive, daring, combativeness","SU/JU":"Success, optimism, approval-winning, luck","SU/SA":"Discipline and purpose through perseverance","SU/UR":"Willful independence; reform-imposing originality","SU/NE":"Idealized self-image; dreams blur reality","SU/PL":"Formidable willpower; control, self-mastery","SU/NN":"Vital alliances with important people","SU/AS":"Self-presentation; immediate personal impact","SU/MC":"Earned recognition; maturing self-realization","MO/ME":"Emotion meets reason; feelings voiced","MO/VE":"Loving sensitivity; the feminine nature","MO/MA":"Emotional impulsiveness; protective aggression","MO/JU":"Expanded feelings; security-seeking optimism","MO/SA":"Emotional restraint; duty; parental conditioning","MO/UR":"Emotional rebellion; intuitive eccentric genius","MO/NE":"Heightened imagination; dreamy sentiment; neglect","MO/PL":"Intense emotional transformation; quiet revolutions","MO/NN":"Seeking helpful connections; relating to publics","MO/AS":"Sensitivity to immediate surroundings; moodiness","MO/MC":"Emotional security shaping life's goals","ME/VE":"Charming expression; love of language","ME/MA":"Sharp quick thinking; argument, agitated speech","ME/JU":"Persuasive expansive knowledge; lucky communications","ME/SA":"Disciplined sober thought; talks delayed","ME/UR":"Inventive detached intellect; tech and astrology","ME/NE":"Inspired or deceptive thinking; confusion","ME/PL":"Obsessive penetrating thought; coercive speech","ME/NN":"Communication networks; finding informants","ME/AS":"Alert awareness of people and environment","ME/MC":"Intellect applied to life's objectives","VE/MA":"Passion: attraction wrestling aggression","VE/JU":"Pleasure, luck, abundance, grace","VE/SA":"Love restricted; sober loyal affection","VE/UR":"Unconventional affection; sudden attractions","VE/NE":"Romantic illusion; artistic mysticism","VE/PL":"Compulsive passion; resources as power","VE/NN":"Pleasant cooperative associations","VE/AS":"The desire to please and charm","VE/MC":"Self-worth through accomplishment; integrated grace","MA/JU":"Abundant energy; lucky bold competition","MA/SA":"Stop-and-go force; harnessed or thwarted drive","MA/UR":"Sudden disruptive action; the short fuse","MA/NE":"Energy diffused; inspired or deceptive action","MA/PL":"Ruthless force; battle against corruption","MA/NN":"Pushy energetic alliance-making","MA/AS":"Energized restless environment","MA/MC":"Fighting for recognition and security","JU/SA":"Expansion-contraction cycles; tempered ambition","JU/UR":"Fortunate breakthroughs; philosophical rebellion","JU/NE":"Visionary idealism; inflated dreams","JU/PL":"Engagement with extremes; large-scale power","JU/NN":"Lucky contacts; beneficial groups","JU/AS":"Inspiring cheerful front; reading motives","JU/MC":"Social leadership; ethical self-image","SA/UR":"Tradition versus innovation; sudden restriction","SA/NE":"Disciplined illusion; chronic evasion and neglect","SA/PL":"Hard relentless work; disciplined upheaval","SA/NN":"Purpose through burdened associations","SA/AS":"Withdrawn reserve; self-imposed isolation","SA/MC":"Hard-won self-reliance; enduring legacy","UR/NE":"Abandoning the outworn; strange confusion","UR/PL":"Obsessive radical independence; deep upheaval","UR/NN":"Unusual sudden alliances","UR/AS":"Disruptive individuality; electric presence","UR/MC":"Adapting to constant change; abrupt notoriety","NE/PL":"Dissolving obsessions; shifting reality itself","NE/NN":"Retreat from associations; group confusion","NE/AS":"Perceiving by intuition, not fact; elusiveness","NE/MC":"Indecisive direction; visionary or lost goals","PL/NN":"Compelling fateful connections; influence networks","PL/AS":"Penetrating intense presence; controlled focus","PL/MC":"Transformation through trials; destiny self-controlled","NN/AS":"Meeting kindred people; community identity","NN/MC":"Allies sharing one's goals and standing","AS/MC":"Experience integrated into growth and recognition"},"quips":{"aspects":{"conjunct":"fusion — the two act as one voice","semisextile":"adjacent and awkward — small adjustments, quiet growth","sextile":"open door — opportunity that works if worked","square":"friction that forces action — the productive crisis","trine":"flow — talent and ease, sometimes too easy","quincunx":"off-balance — constant correction, nothing settles","opposite":"face-off — awareness through the other; seek the balance point"},"planets":{"Sun":"vitality, identity, the will — where you shine","Moon":"mood, needs, the inner tide — daily life","Mercury":"mind and voice — the messenger","Venus":"love, money, taste — what you draw in","Mars":"drive, heat, the fight — how you act","Jupiter":"growth, faith, luck — where you expand","Saturn":"structure, tests, time — where you build or get built","Uranus":"the lightning — sudden freedom, breaks, genius","Neptune":"the fog and the dream — dissolve, inspire, deceive","Pluto":"the deep lever — power, purge, rebirth","Chiron":"the wound that teaches","Node":"the appointment — destiny's meeting point","America":"the American thread in a personal story"},"tech":{"stacked":"Rule of Three: 3+ independent voices on one theme — this is real, expect an event window","t2p":"transit to PROGRESSED point — hits the life as lived now; stronger than natal contact (Teal)","p2n":"progressed-to-natal — the slow inner clock striking a natal promise; theme lasts months","redflag":"Saturn/Uranus hard to progressed Sun or Moon — Teal's red flag: structural stress or sudden break; drive carefully","nodetimer":"node contact — a timer, not a cause: meetings, joinings, separations that feel fated","durability":"Saturn conjunct the Node — Teal's durability aspect: what forms now is built to last","eclipsefire":"Mars re-crossing an eclipse degree re-detonates that eclipse's story","skyrepeat":"the sky repeats an active pair — Teal's date-targeter: the theme's trigger day","satreturn":"Saturn return — the great audit: keep what is true, the rest goes; a structure for the next 29 years","marsreturn":"Mars return — a fresh 2-year cycle of drive; how you start it colors the whole cycle","lunarreturn":"lunar return — the month's chart; angles and Moon house set the month's tone","climactic":"LR Ascendant matches SR Ascendant sign — Teal's CLIMACTIC MONTH: the year's promise comes due","srsunangle":"LR Sun on a Solar Return angle — an eventful month flagged by the year-chart","progstation":"a progressed outer STATIONS — rare and weighty: a life-long undercurrent changes direction","progsign":"a progressed planet changes sign/house — the backdrop quietly re-colors for years","progouter":"progressed outers mirror the birth chart — only their stations and sign changes matter (Katie's rule)","progjupiter":"prog Jupiter — fast enough to matter sometimes; weigh it consciously","midpointhit":"a midpoint axis lit — the pair's combined theme is activated where it lands (mod-45)","tree":"a midpoint tree — every pair whose combined energy feeds this point","mundanemidpoint":"event charts speak midpoints loudest (Munkasey) — in mundane work treat a lit axis literally","nodelev":"a natal point on a planetary node — the personal raised to collective significance (Jones)","nodetrigger":"a transit to a node-contact degree — these degrees time the biography (the Turing pattern)","eraaspect":"a progressed aspect in orb for decades — the backdrop of an era, not a timer","juNN":"Jupiter's north node — the most progressive vision; new faith offered to the collective","juSN":"Jupiter's south node — the history of belief; old systems of thought","saNN":"Saturn's north node — the maturation of person and society","saSN":"Saturn's south node — old structures; the conditioning past","urNN":"Uranus's north node — liberation and breakthrough; technology serving freedom","urSN":"Uranus's south node — collective trauma's origins; fundamentalism's shadow","neNN":"Neptune's north node — the deepest healing vision; the creative offering","neSN":"Neptune's south node — the old dream; inherited images of the divine","plNN":"Pluto's north node — the greatest possible transformation","plSN":"Pluto's south node — the past's compulsive grip on security"},"nodes_full":{"_readme":"Fuller node interpretations (Jones book digest, 2026-06-12) — 'expand a bit, lay it out' per Katie.","juNN":"Jupiter's north node (Cancer, our era): the most progressive vision available — faith re-rooted in home, belonging, and the felt sense of a human family. A point here offers its function as new collective belief; what this person teaches, publishes, or stands for is meant to feed people, not empires. The degree stays live for life: transits here time the milestones of the calling.","juSN":"Jupiter's south node (Capricorn, our era): the whole inheritance of organized belief — doctrine, institution, the law of the fathers. A point here carries the gift AND the weight of old systems of thought; the work is to keep the wisdom while letting the scaffolding go. Often marks a born scholar of traditions.","saNN":"Saturn's north node (Cancer, our era): maturity re-imagined — structure in service of care, authority that protects rather than dominates. A point here is asked to BUILD something that makes people feel safe; responsibility becomes nourishing. Events here tend to formalize: contracts, offices, foundations.","saSN":"Saturn's south node (Capricorn, our era): the conditioning past itself — hierarchy, scarcity logic, the rules as they were handed down. A point here knows the old order from the inside (a gift for administration and history) and is haunted by it; the Jones war-tables open conflicts on contacts to this axis. What forms here is durable, for better and worse.","urNN":"Uranus's north node (Gemini): liberation through learning out loud — plural inquiry, conversation, technology that connects. A point here is meant to break a silence: name the thing, share the data, democratize the insight. Breakthroughs (and sudden exposure) time to this degree.","urSN":"Uranus's south node (Sagittarius): the collective trauma carried in belief itself — fundamentalism, the crusade, truth weaponized. A point here has lived inside a conviction system and bears its scars; the medicine is many small truths over one big one. Shocks here re-open old certainty wounds before freeing them.","neNN":"Neptune's north node (Leo): the healing vision delivered PERSONALLY — creativity as offering, the heart on stage for something larger. A point here is asked: what does your one performance give the collective dream? Wars end and treaties sign on contacts here (Jones); grace arrives through individual gesture.","neSN":"Neptune's south node (Aquarius): the old collective dream — utopias, ideologies, the group's inherited image of heaven. A point here is fluent in mass yearning (propaganda or poetry, same antenna); the work is discernment between the dream that heals and the fog that dissolves.","plNN":"Pluto's north node (Cancer, our era): transformation completed as homecoming — power composted into protection of the vulnerable. A point here can metabolize collective crisis into rebirth; it marks people through whom the deep change becomes personal, livable, real. Pluto was DISCOVERED on this node.","plSN":"Pluto's south node (Capricorn, our era): the underworld of civilization — dynasty, purge, the compulsive reach for control that built and broke empires. The 2020 Saturn–Pluto conjunction sat exactly here. A point here touches the master complex of the age: security through domination, and the long reckoning with it."}},"dignities":{"Mars":{"rulership":["Aries","Scorpio"],"exaltation":"Capricorn","detriment":["Libra","Taurus"],"fall":"Cancer"},"Venus":{"rulership":["Taurus","Libra"],"exaltation":"Pisces","detriment":["Scorpio","Aries"],"fall":"Virgo"},"Mercury":{"rulership":["Gemini","Virgo"],"exaltation":"Virgo","detriment":["Sagittarius","Pisces"],"fall":"Pisces"},"Moon":{"rulership":["Cancer"],"exaltation":"Taurus","detriment":["Capricorn"],"fall":"Scorpio"},"Sun":{"rulership":["Leo"],"exaltation":"Aries","detriment":["Aquarius"],"fall":"Libra"},"Pluto":{"rulership":["Scorpio"],"detriment":["Taurus"]},"Jupiter":{"rulership":["Sagittarius","Pisces"],"exaltation":"Cancer","detriment":["Gemini","Virgo"],"fall":"Capricorn"},"Saturn":{"rulership":["Capricorn","Aquarius"],"exaltation":"Libra","detriment":["Cancer","Leo"],"fall":"Aries"},"Uranus":{"rulership":["Aquarius"],"detriment":["Leo"]},"Neptune":{"rulership":["Pisces"],"detriment":["Virgo"]}},"rulership":{"Aries":["Mars"],"Taurus":["Venus"],"Gemini":["Mercury"],"Cancer":["Moon"],"Leo":["Sun"],"Virgo":["Mercury"],"Libra":["Venus"],"Scorpio":["Mars","Pluto"],"Sagittarius":["Jupiter"],"Capricorn":["Saturn"],"Aquarius":["Saturn","Uranus"],"Pisces":["Jupiter","Neptune"]}};
(function(){
var C=window.KKCORPUS;
var ASPGLYPH={conjunction:"☌",opposition:"☍",square:"□","trine":"△",sextile:"⚹",
 quincunx:"⚻","semi-sextile":"⚺","semi-square":"∠","sesqui-square":"⚼"};
var HELPFUL={trine:1,sextile:1,"semi-sextile":1};
var ORD=["","1st","2nd","3rd","4th","5th","6th","7th","8th","9th","10th","11th","12th"];
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;")}
function cap(s){return s?s.charAt(0).toUpperCase()+s.slice(1):s}
function parse(spec){
  var o={},parts=String(spec).split(";");
  parts.forEach(function(p,i){var c=p.indexOf(":");if(c<0)return;
    var k=p.slice(0,c).trim(),v=p.slice(c+1).trim();
    if(i===0){o.type=k;o.val=v}else o[k]=v});
  return o}
function kw(cat,key){var d=C.kw[cat];if(!d)return null;
  return d[key]||d[String(key).toLowerCase()]||null}
function chips(label,arr,max){if(!arr||!arr.length)return "";
  var h='<div class="kki-chipgrp">'+esc(label)+'</div>';
  arr.slice(0,max||14).forEach(function(p){h+='<span class="kki-chip">'+esc(p)+'</span>'});
  return h}
function sec(title,html,coll){if(!html)return "";
  return '<div class="kki-sec'+(coll?' kki-coll':'')+'"><div class="kki-h" onclick="this.parentNode.classList.toggle(\'kki-coll\')">'+
    esc(title)+'<span class="kki-chev">▾</span></div><div class="kki-cnt">'+html+'</div></div>'}
function para(label,text){if(!text)return "";
  return '<p class="kki-p">'+(label?'<span class="kki-lbl">'+esc(label)+' — </span>':'')+esc(text)+'</p>'}
function dignity(planet,sign){var d=C.dignities[planet];if(!d||!sign)return null;
  if((d.rulership||[]).indexOf(sign)>=0)return["rulership",C.blocks.dignity_text.rulership];
  if(d.exaltation===sign)return["exaltation",C.blocks.dignity_text.exaltation];
  if((d.detriment||[]).indexOf(sign)>=0)return["detriment",C.blocks.dignity_text.detriment];
  if(d.fall===sign)return["fall",C.blocks.dignity_text.fall];
  return null}
function pairRec(p1,p2){if(!p1||!p2)return null;
  return C.pairs[p1+"-"+p2]||C.pairs[p2+"-"+p1]||null}
function synodRec(p1,p2){if(!p1||!p2)return null;
  return C.blocks.synods[p1+"-"+p2]||C.blocks.synods[p2+"-"+p1]||null}
function rankRec(p1,p2){var r=C.blocks.rankings,hit=null;
  ["dangerous","fortunate"].forEach(function(k){r[k].forEach(function(e){
    var pp=e.pair.split("-");
    if((pp[0]===p1&&pp[1]===p2)||(pp[0]===p2&&pp[1]===p1))hit={kind:k,rec:e}})});
  return hit}
function f250sig(planet,sign){var m={"Pluto|Aquarius":"pluto_aquarius","Uranus|Gemini":"uranus_gemini",
  "Jupiter|Leo":"jupiter_leo"};var k=m[planet+"|"+sign];
  return k?C.blocks.f250_signatures[k]:null}
function aspKwKey(asp,texture){
  if(texture==="upper"||texture==="lower"){var t=texture+" "+asp;if(kw("aspects",t))return t}
  if(texture==="dissociate"&&kw("aspects","dissociate "+asp))return "dissociate "+asp;
  return asp}

// ---- RELATIONAL ENGINE (2026-06-12) ----
// "It's not just Jupiter in Capricorn in the 7th house. This is Jupiter exactly opposite
// the Sun in the 1st, and sextile the chart ruler Pisces Moon in the 9th which it rules
// over. Jupiter being ruled by my Saturn in Aries. All of these layers matter."
// — Katie, asking for depth that tells the truth.

var CHART=null;    // set by view via KKI.setChart(data)
var SIGN2HOUSE={}; // sign→house# for quick lookup (computed on setChart)
var RULER_MAP={};  // sign→[planet,...] from C.rulership

function initRulerMap(){
  if(C.rulership)Object.keys(C.rulership).forEach(function(s){RULER_MAP[s]=C.rulership[s]})}
initRulerMap();

function signOfDeg(deg){
  var signs=["Aries","Taurus","Gemini","Cancer","Leo","Virgo","Libra","Scorpio","Sagittarius","Capricorn","Aquarius","Pisces"];
  return signs[Math.floor(((deg%360)+360)%360/30)]}

function houseOfDeg(deg){
  // WHOLE SIGN: house = sign-count from ASC sign, not degree-offset
  if(!CHART||!CHART.asc)return null;
  var ascSign=Math.floor(CHART.asc/30);
  var degSign=Math.floor(((deg%360+360)%360)/30);
  return((degSign-ascSign+12)%12)+1}

function findRulers(sign){return RULER_MAP[sign]||[]}

function chartPos(name){
  if(!CHART||!CHART.pos)return null;
  for(var i=0;i<CHART.pos.length;i++){
    var p=CHART.pos[i];if(p[0]===name)return{name:p[0],sign:p[1],deg:p[2],rx:p[3],lon:p[4],
      house:houseOfDeg(p[4])}}
  return null}

function chartAspects(name){
  if(!CHART||!CHART.asp)return[];
  var out=[];
  CHART.asp.forEach(function(a){
    var m=a.t.match(/^(\S+)\s+(.+?)\s+(\S+)$/);if(!m)return;
    var p1=m[1],asp=m[2],p2=m[3];
    if(p1===name)out.push({other:p2,aspect:asp,orb:a.o,exact:a.x,applying:a.ap});
    else if(p2===name)out.push({other:p1,aspect:asp,orb:a.o,exact:a.x,applying:a.ap})});
  return out.sort(function(a,b){return a.orb-b.orb})}

function planetsGoverned(planet){
  // find all chart planets sitting in signs that 'planet' rules
  if(!CHART||!CHART.pos)return[];
  var ruled=[];
  Object.keys(RULER_MAP).forEach(function(s){if(RULER_MAP[s].indexOf(planet)>=0)ruled.push(s)});
  if(!ruled.length)return[];
  var out=[];
  CHART.pos.forEach(function(p){
    if(p[0]!==planet&&ruled.indexOf(p[1])>=0)
      out.push({name:p[0],sign:p[1],deg:p[2],rx:p[3],lon:p[4],house:houseOfDeg(p[4])})});
  return out}

function dispositorChain(planet,sign,depth){
  // walk the chain: who rules this planet's sign? and who rules THAT planet's sign? etc.
  if(!CHART||depth>4)return[];
  var rulers=findRulers(sign);if(!rulers.length)return[];
  var chain=[];
  rulers.forEach(function(r){
    if(r===planet)return; // self-ruled, skip
    var rp=chartPos(r);
    if(rp){
      var d=dignity(r,rp.sign);
      chain.push({name:r,sign:rp.sign,house:rp.house,deg:rp.deg,rx:rp.rx,
        dignity:d,deeper:dispositorChain(r,rp.sign,(depth||0)+1)})}});
  return chain}

function mutualReception(p1name,p1sign,p2name,p2sign){
  // TRUE mutual reception: p1 rules p2sign AND p2 rules p1sign
  var p1RulesP2Sign=findRulers(p2sign).indexOf(p1name)>=0;
  var p2RulesP1Sign=findRulers(p1sign).indexOf(p2name)>=0;
  return p1RulesP2Sign&&p2RulesP1Sign}

function isChartRuler(planet){
  if(!CHART)return false;
  var ascSign=signOfDeg(CHART.asc);
  return findRulers(ascSign).indexOf(planet)>=0}

function aspName(a){return a.charAt(0).toUpperCase()+a.slice(1).replace("semi-","semi‑").replace("sesqui-","sesqui‑")}
function aspGlyph(a){return ASPGLYPH[a.toLowerCase()]||a}
function fmtOrb(o){return o<0.1?"exact":(o.toFixed(1)+"°")}

function render(o){
  var reg=o.reg==="m"?"mundane":(o.reg==="n"?"natal":null);
  var title="",sub="",kwHtml="",mythHtml="",synHtml="",ctxHtml="",comboHtml="",srcHtml="";
  var P=C.blocks.planets,S=C.blocks.signs,H=C.blocks.houses,A=C.blocks.aspects;

  function planetLayer(name){
    var b=P[name];if(!b)return;
    kwHtml+=chips(name,kw("planets",name));
    if(b.myth)mythHtml+='<p class="kki-myth"><span class="kki-god">'+esc(name)+' · </span>'+esc(b.myth)+'</p>';
    if(!reg||reg==="natal")synHtml+=para(name,b.natal);
    if(!reg||reg==="mundane")synHtml+=para(name+" · in the nation",b.mundane);
    if(reg==="mundane"&&b.actor)ctxHtml+='<div class="kki-ctx"><b>Who this is:</b> '+esc(b.actor)+'</div>'}
  function signLayer(name){
    var b=S[name];if(!b)return;
    kwHtml+=chips(name,kw("signs",name));
    synHtml+=para(name,b.text);
    if(reg!=="natal")synHtml+=para(name+" · in the nation",b.mundane)}
  function houseLayer(n){
    var b=H[String(n)];if(!b)return;
    var lbl=ORD[+n]+" house";
    if(!reg||reg==="natal"){kwHtml+=chips(lbl,kw("houses",String(n)));synHtml+=para(lbl,b.natal)}
    if(!reg||reg==="mundane"){kwHtml+=chips(lbl+" · mundane",kw("mundane_houses",String(n)));synHtml+=para(lbl+" · in the nation",b.mundane)}}

  if(o.type==="planet"){
    var pl=cap(o.val);title=pl;
    if(o.sign)title+=" in "+cap(o.sign);
    if(o.house)title+=" · "+ORD[+o.house]+" house";
    planetLayer(pl);
    if(o.sign){signLayer(cap(o.sign));
      var d=dignity(pl,cap(o.sign));
      if(d)ctxHtml+='<div class="kki-ctx '+(d[0]==="rulership"||d[0]==="exaltation"?"kki-good":"kki-warn")+'"><b>Dignity:</b> '+pl+" in "+cap(o.sign)+" is "+esc(d[1])+'</div>';
      var sg=f250sig(pl,cap(o.sign));
      if(sg)comboHtml+='<div class="kki-combo">'+esc(sg)+'</div>'}
    if(o.house)houseLayer(o.house)}
  else if(o.type==="sign"){title=cap(o.val);signLayer(cap(o.val));
    var rul=Object.keys(C.dignities).filter(function(p){return (C.dignities[p].rulership||[]).indexOf(cap(o.val))>=0});
    if(rul.length)ctxHtml+='<div class="kki-ctx"><b>Ruler:</b> '+rul.join(" · ")+'</div>'}
  else if(o.type==="house"){title=ORD[+o.val]+" house"+(reg?" — "+reg:"");houseLayer(o.val)}
  else if(o.type==="aspect"){
    var asp=o.val.toLowerCase(),p1=o.p1?cap(o.p1):null,p2=o.p2?cap(o.p2):null;
    var g=ASPGLYPH[asp]||asp;
    title=(p1&&p2)?(p1+" "+g+" "+p2):cap(asp);
    if(o.texture)sub=cap(o.texture)+" "+asp;
    var ab=A[asp];
    kwHtml+=chips(aspKwKey(asp,o.texture),kw("aspects",aspKwKey(asp,o.texture)));
    if(ab){synHtml+=para(cap(asp),ab.dyn);if(reg!=="natal")synHtml+=para("In the nation",ab.mundane)}
    if(o.texture&&C.blocks.texture[o.texture])ctxHtml+='<div class="kki-ctx">'+esc(C.blocks.texture[o.texture])+'</div>';
    if(p1&&p2){
      if(p1!==p2){planetLayer(p1);planetLayer(p2)}else planetLayer(p1);
      var pr=pairRec(p1,p2);
      if(pr){var hostile=ab?!(HELPFUL[asp]):(asp!=="trine"&&asp!=="sextile");
        var t=hostile?(pr.hostile||null):(pr.helpful||null);
        if(t)synHtml+=para("This pair, this aspect",t);
        else (pr.text||[]).slice(0,2).forEach(function(x){synHtml+=para(null,x)});
        if(pr.current_text)comboHtml+='<div class="kki-combo"><b>Now:</b> '+esc(pr.current_text)+'</div>';
        if(pr.trigger)ctxHtml+='<div class="kki-ctx"><b>As trigger:</b> '+esc(pr.trigger)+'</div>';
        if(pr.arcs&&pr.arcs.length){var ah="";pr.arcs.forEach(function(a){
          ah+='<span class="kki-arc" data-kkarc="'+esc(a.arc)+'">'+esc(a.arc)+'</span>'});
          comboHtml+=sec("Chronicle arcs driven by this pair",ah)}
        if(pr.note)srcHtml='<div class="kki-src">full delineation: <a href="obsidian://open?vault='+
          encodeURIComponent("Freedom 250 Chronicle")+'&file='+encodeURIComponent(pr.note.replace(/\.md$/,""))+'">'+esc(pr.note.split("/").pop())+'</a></div>'}
      var sy=synodRec(p1,p2);
      if(sy)ctxHtml+='<div class="kki-ctx"><b>The '+esc(sy.years)+' cycle:</b> '+esc(sy.text)+'</div>';
      var rk=rankRec(p1,p2);
      if(rk){var bad=rk.kind==="dangerous";var applies=bad?!(HELPFUL[asp]):(HELPFUL[asp]||asp==="conjunction");
        if(applies)ctxHtml+='<div class="kki-ctx '+(bad?"kki-warn":"kki-good")+'"><b>'+
          (bad?"Among the most dangerous in a mundane chart":"Among the most fortunate in a mundane chart")+
          ':</b> '+esc(rk.rec.text)+'</div>'}}
  }
  else if(o.type==="pair"){
    var pp=o.val.split(/[-–]/).map(cap);title=pp[0]+"–"+pp[1];sub="the pair as one storyline";
    planetLayer(pp[0]);planetLayer(pp[1]);
    var pr2=pairRec(pp[0],pp[1]);
    if(pr2){(pr2.text||[]).forEach(function(x){synHtml+=para(null,x)});
      if(pr2.helpful)synHtml+=para("Helpful aspects",pr2.helpful);
      if(pr2.hostile)synHtml+=para("Hostile aspects",pr2.hostile);
      if(pr2.current_text)comboHtml+='<div class="kki-combo"><b>Now:</b> '+esc(pr2.current_text)+'</div>';
      if(pr2.cycle)sub=pr2.cycle+(pr2.current?" · "+pr2.current:"");
      if(pr2.arcs&&pr2.arcs.length){var ah2="";pr2.arcs.forEach(function(a){
        ah2+='<span class="kki-arc" data-kkarc="'+esc(a.arc)+'">'+esc(a.arc)+'</span>'});
        comboHtml+=sec("Chronicle arcs driven by this pair",ah2)}
      if(pr2.note)srcHtml='<div class="kki-src">full delineation: <a href="obsidian://open?vault='+
        encodeURIComponent("Freedom 250 Chronicle")+'&file='+encodeURIComponent(pr2.note.replace(/\.md$/,""))+'">'+esc(pr2.note.split("/").pop())+'</a></div>'}
    var sy2=synodRec(pp[0],pp[1]);
    if(sy2)ctxHtml+='<div class="kki-ctx"><b>The '+esc(sy2.years)+' cycle:</b> '+esc(sy2.text)+'</div>'}
  else if(o.type==="phase"){
    var ph=C.blocks.moon_phases[o.val];title={new:"New Moon",first_quarter:"First Quarter",full:"Full Moon",last_quarter:"Last Quarter"}[o.val]||cap(o.val);
    if(o.sign){title+=" in "+cap(o.sign)}
    synHtml+=para(null,ph);
    if(o.eclipse)synHtml+=para("Eclipse",C.blocks.moon_phases.eclipse_amp);
    if(o.sign)signLayer(cap(o.sign));
    kwHtml=chips("Moon",kw("planets","Moon"))+kwHtml}
  else if(o.type==="point"){
    var pb=C.blocks.points[o.val];title={ASC:"Ascendant",MC:"Midheaven",NN:"North Node",SN:"South Node"}[o.val]||o.val;
    if(pb){if(!reg||reg==="natal")synHtml+=para("Natal",pb.natal);
      if(!reg||reg==="mundane")synHtml+=para("Mundane",pb.mundane)}
    if(o.sign)signLayer(cap(o.sign))}
  else if(o.type==="mid"){
    title="Midpoint "+o.val;var mt=C.midpoints[o.val];
    synHtml+=para(null,mt||"(no Munkasey text for this pair)");
    sub="mod-45 midpoint"}
  else if(o.type==="sig"){
    title=o.title||"Freedom 250 signature";
    comboHtml+='<div class="kki-combo">'+esc(C.blocks.f250_signatures[o.val]||"")+'</div>'}
  else if(o.type==="node"){
    var nf=C.quips.nodes_full&&C.quips.nodes_full[o.val];
    title=o.title||("Planetary node "+o.val);
    synHtml+=para(null,typeof nf==="string"?nf:JSON.stringify(nf))}
  if(o.title)title=o.title;

  // ONE WOVEN READING (Katie 2026-06-12: "This is mine — ALL of my viewpoints"):
  // no source-labeled sections — myth opens, the reading flows, judgments follow,
  // her keyword chips close it, the chronicle layer stays as the one named section.
  var body="";
  if(mythHtml)body+='<div class="kki-sec">'+mythHtml+'</div>';
  if(synHtml)body+='<div class="kki-sec">'+synHtml+'</div>';
  if(ctxHtml)body+='<div class="kki-sec">'+ctxHtml+'</div>';
  if(kwHtml)body+='<div class="kki-sec"><div class="kki-rule"></div>'+kwHtml+'</div>';
  if(comboHtml)body+=sec("This chronicle",comboHtml);
  if(!body)body='<p class="kki-p" style="color:#9a8c68">No interpretation found for spec: '+esc(JSON.stringify(o))+'</p>';
  body+=srcHtml;
  return {title:title,sub:sub,body:body}}

function drawer(){var d=document.getElementById("kki-drawer");if(d)return d;
  d=document.createElement("div");d.id="kki-drawer";
  d.innerHTML='<div id="kki-head"><div style="flex:1"><div id="kki-title"></div><div id="kki-sub"></div></div>'+
    '<button id="kki-x" title="close (Esc)">✕</button></div><div id="kki-body"></div>';
  document.body.appendChild(d);
  d.querySelector("#kki-x").onclick=KKI.close;
  document.addEventListener("keydown",function(e){if(e.key==="Escape")KKI.close()});
  d.addEventListener("click",function(e){
    var a=e.target.closest("[data-kkarc]");
    if(a){var fn=window.goToArc||(window.parent&&window.parent.goToArc);
      if(fn){try{fn(a.getAttribute("data-kkarc"))}catch(_){}}
      else if(window.parent!==window)window.parent.postMessage({type:"goToArc",arc:a.getAttribute("data-kkarc")},"*")}});
  return d}

window.KKI={
  setChart:function(data){CHART=data;
    // precompute sign→house map for quick lookup
    if(data&&data.asc){SIGN2HOUSE={};
      var ascSign=signOfDeg(data.asc);var signs=["Aries","Taurus","Gemini","Cancer","Leo","Virgo","Libra","Scorpio","Sagittarius","Capricorn","Aquarius","Pisces"];
      var base=signs.indexOf(ascSign);
      for(var i=0;i<12;i++)SIGN2HOUSE[signs[(base+i)%12]]=i+1}},
  open:function(spec){var o=typeof spec==="string"?parse(spec):spec;var r=render(o);var d=drawer();
    d.querySelector("#kki-title").innerHTML=esc(r.title);
    d.querySelector("#kki-sub").innerHTML=esc(r.sub||"");
    d.querySelector("#kki-body").innerHTML=r.body;
    d.querySelector("#kki-body").scrollTop=0;
    d.classList.add("kki-open")},
  close:function(){var d=document.getElementById("kki-drawer");if(d)d.classList.remove("kki-open")}};

document.addEventListener("click",function(e){
  var el=e.target.closest("[data-kk]");
  if(el){e.stopPropagation();KKI.open(el.getAttribute("data-kk"))}},true);
})();
// Auto-register chart data with the relational interpretation engine.
// Views that define NATAL get relational readings; other views can call KKI.setChart() directly.
(function(){
  if(typeof KKI==="undefined"||!KKI.setChart)return;
  // Try global NATAL (Katie's Sky, Almanac day charts, etc.)
  try{if(typeof NATAL!=="undefined"&&NATAL&&NATAL.pos){KKI.setChart(NATAL);return}}catch(_){}
  // Try window.NATAL explicitly
  try{if(window.NATAL&&window.NATAL.pos){KKI.setChart(window.NATAL);return}}catch(_){}
})();
